insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('1', '1', 'getting-in', 'Getting in', 'Why do I have to fill in my whole profile before I can start?', 'This part is the start, not a form before the start.

The questions Ally asks here are how it learns the way you think and work. Your Founder DNA builds up on the right side of the screen as you answer, so you can watch it take shape.

There are 17 questions in four short parts. Ally asks about you, then what you are building, then what you already know, and finishes with your biggest challenge and where you want to be.

Skip it and Ally would be guessing about you. Then the diagnosis at the end would be a general one, not yours.', 'walked', 'answered', 'true', NULL, '{/guided/profile}', '2026-09-04', 'Counted the sections and fields on the profile build screen: Personal details (5), Understanding where you are (4), What do you know (5), Final questions (3).', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('2', '1', 'getting-in', 'Getting in', 'What happens in this diagnosis, and how long will it take?', 'About 20 minutes in total. It is a conversation, not a form.

There are three parts. First you and Ally talk, which takes about 10 minutes. Then Ally connects what it learned about you to how your business runs. Then you get your report.

The report gives you the root cause holding you back, your blind spots, and clear next steps.

You do not have to do it all at once. You can stop and come back.', 'walked', 'answered', 'true', NULL, '{/guided/expectation}', '2026-09-04', 'Read the three phases and timings off the ''How it works'' screen.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('3', '1', 'getting-in', 'Getting in', 'Do I have to do Founder DNA first? Can I skip to the business part?', 'No, Founder DNA cannot be skipped. It is the first part, and everyone does it.

The reason is that it is what makes the report yours. Ally looks at your business through what it learns about you — how you decide, where you push, where you get stuck. Without that, you would get general business advice, which you can find anywhere.

It is also the shorter part. Once it is done, the business questions move faster, because Ally already knows how to read your answers.', 'policy', 'answered', 'true', NULL, '{/guided/profile}', '2026-09-04', 'Product decision confirmed by the team: Founder DNA is mandatory and cannot be skipped by any route.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('4', '1', 'getting-in', 'Getting in', 'I picked the wrong stage. Can I change it?', NULL, 'walked', 'open_for_team', 'false', 'Left deliberately unanswered pending a team discussion. See OPEN-FOR-TEAM.md.', '{/app/profile}', NULL, NULL, NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('5', '1', 'getting-in', 'Getting in', 'Is this going to try to sell me something?', 'There is one upsell, and you are looking at it: the plans page.

Ally starts at Rs 199. That is paid once and buys you a month -- there is no subscription and nothing renews on you. It gives you the full diagnosis and your complete report.

Inside the diagnosis, nothing is being sold to you. Ally is not steering you toward a purchase, and the questions are not a funnel -- they are what the report is built from.

Two other things cost money if you want them: a bigger monthly plan, and a discovery call with our team at Rs 300 for 30 minutes.

No cold calls, and no sales emails.', 'policy', 'answered_pending_product_change', 'false', NULL, '{/app/billing}', '2026-09-06', 'Team decision 2026-09-06. Starter: Rs 199 paid ONCE, buying one month -- it does not auto-renew. Plus (Rs 450) and Pro (Rs 999) are monthly subscriptions, with 12 months for the price of 10 if paid annually. A discovery call is Rs 300 per 30 minutes on any plan. GST is included in every price shown.', 'CONFLICTS WITH THE LIVE PRODUCT. The app still ships a Free tier: the test account shows ''Ally Free'' at ₹0, and the plan catalog defines free/starter/pro at ₹0/₹450/₹999 with no ₹199 tier. This answer is correct against the decision and wrong against the product until the catalog is changed. Do not publish it before then.', 'HELD until PUBLIC_LAUNCH is on -- describes the paid-only launch state. REVISED 2026-09-06: Starter is a one-off payment for a month, not a monthly subscription. The 2026-09-05 draft said it renewed monthly.', 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('6', '1', 'getting-in', 'Getting in', 'I closed the onboarding halfway. Do I start again?', 'No, you carry on from where you stopped.

When you sign in again, Ally shows you a "Welcome back" screen with how far you got — for example 64% of the way to your report. It shows your progress on Founder DNA and Business DNA separately.

Click Continue assessment and you go straight back to the next question. Nothing you already answered is lost.', 'walked', 'answered', 'true', NULL, '{/guided/resume}', '2026-09-04', 'Opened the resume screen on a part-finished account: it showed 64%, Founder DNA 64%, Business DNA 55%, and a Continue assessment button.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('7', '1', 'getting-in', 'Getting in', 'What was that quick tour? Can I see it again?', 'Yes, any time.

Go to Profile, find Product tour under Preferences, and click Replay tour.

It walks you through the whole app in 14 short steps, starting at your Compass. There is a Skip button on every step, so you can stop whenever you like.', 'walked', 'answered', 'true', NULL, '{/app/profile}', '2026-09-04', 'Clicked Replay tour and ran it. Step 1 of 14 opened on the Compass; Skip ended it and returned to the app.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('8', '1', 'getting-in', 'Getting in', 'Why did it read my own answers back to me?', 'So you can correct anything before Ally builds on it.

That screen shows your founder profile in your own words, plus Ally''s early read of you. Everything on it can be edited. If a word is not quite right, change it, then confirm.

It matters because everything after this is built on those answers. Fixing something here is much easier than disagreeing with your report later.', 'walked', 'answered', 'true', NULL, '{/guided/summary}', '2026-09-04', 'Opened the summary screen: it reads back each profile field, shows ''Ally''s early read'', and says to reword anything before confirming.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('9', '1', 'getting-in', 'Getting in', 'What is the "validation" step checking?', 'It is Ally checking that it understood you correctly.

Ally shows you one sentence about how you work — something it worked out from your answers — and asks if it is true. You can say yes, or say it is mostly true with some nuance.

It is a short step but an important one. Your answer shapes the questions that come next, so if the sentence feels wrong, say so.', 'walked', 'answered', 'true', NULL, '{/guided/validate}', '2026-09-04', 'Opened the validate screen: it states one inferred sentence, says ''Your answer shapes everything that comes next'', and offers ''Yes — that''s me'' or ''Mostly, with nuance''.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('10', '1', 'getting-in', 'Getting in', 'What order am I meant to do all this in?', 'Ally walks you through it, so you do not have to plan anything.

The order is: sign in, a short "how it works" screen, meeting Ally, then building your founder profile. After that Ally shows you a summary of your answers to confirm, checks it understood you, and asks what feels most stuck right now.

Then the diagnosis starts, and your report comes at the end.

After the report, the rest of the app opens up and you can use it in any order you like.', 'walked', 'answered', 'true', NULL, '{/guided/expectation}', '2026-09-04', 'Walked every guided screen in sequence and recorded the order.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('11', '1', 'getting-in', 'Getting in', 'Do I have to do "current problem" before the diagnosis?', 'Yes, but it is short — one question.

Ally asks what feels most stuck right now, in your own words. There are a few quick options if it helps, like growth being flat or cash feeling tight, but you can just describe it yourself.

Do not try to work out the cause. That is Ally''s job. Just describe what you are seeing. The Start diagnosis button is right there, and the diagnosis begins from what you wrote.', 'walked', 'answered', 'true', NULL, '{/guided/problem}', '2026-09-04', 'Opened the problem screen: one free-text field, three suggested chips, and a Start diagnosis button. Its own words: ''Don''t diagnose it — just describe it.''', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('12', '1', 'getting-in', 'Getting in', 'Can I sign in with Google, or only email?', 'Email only at the moment. There is no Google or LinkedIn sign-in yet.

You sign in with your email and password.

If it is your first time, or you have forgotten your password, use the "Email me a code" link on the sign-in page. We send a code to your email and you get in with that.', 'walked', 'answered', 'true', NULL, '{/guided/login}', '2026-09-04', 'Read the LIVE sign-in page at goxlally.ai while signed out. It offers email + password and ''First time here, or forgotten your password? Email me a code''. No Google or LinkedIn buttons are present.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('13', '1', 'getting-in', 'Getting in', 'Do I need a registered company to use this?', 'No. Ally never asks for company registration papers, a GST number, or anything official.

When you build your profile, Ally asks what you are building, who you serve, and what industry you are in. You can answer all of that without a registered company.

If your business is not registered yet, that is completely fine.', 'walked', 'answered', 'true', NULL, '{/guided/profile}', '2026-09-04', 'Read all 17 profile-build fields. None asks for registration, GST, or any legal document.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('14', '1', 'getting-in', 'Getting in', 'I don''t have a business yet, just an idea. Is this for me?', 'Yes. Ally is built for people at that point too.

When you start, you tell Ally what stage you are at, and "just exploring an idea" is one of the choices. Ally then asks you different questions from someone running a business with a team.

One thing to know: at the idea stage your report will not include a business health score, because there is not enough of a business to score yet. You get a read on you as a founder and on the idea instead.', 'walked', 'answered', 'true', NULL, '{/guided/profile}', '2026-09-04', 'The live landing page lists aspiring founders as an audience and shows an ''Aspiring'' starting stage. The profile build asks for entrepreneurial stage as its second question.', NULL, NULL, 'group-01-getting-in.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('15', '2', 'during-the-diagnosis', 'During the diagnosis', 'Why is it asking me personal questions? I came here for business help.', 'Because how you work shapes what happens in your business.

Ally starts with you — how you decide, what you push on, where you get stuck — and then looks at your business through that. It is what makes the report yours instead of general advice.

The personal part is the shorter one. Once Ally understands how you think, the business questions go faster and land closer to your real situation.

Nothing you say here is shared with anyone.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'The live diagnosis opened on a ''Founder Psychology'' category and moved to ''Idea & Validation'' after one answer.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('16', '2', 'during-the-diagnosis', 'During the diagnosis', 'Why did it only ask me 14 questions? I expected more.', 'The number depends on the stage you are at, and 14 is the number for the earliest stage.

If you are still working on an idea, there is less business to look at, so Ally asks fewer questions. Founders further along get around 30.

It is not a fixed list either. Ally chooses each question after reading your last answer, so a shorter set that follows what you actually said tells it more than a long form everyone fills in.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'Per-stage budgets read from founder_stages: Ideation 14, Validation 20, Prototype/MVP 24, Early Traction 30, Growth 30, Expansion 32, Maturity 32, Exit 30.', NULL, 'Do not publish the full budget table to founders. ''Fourteen at the earliest stage, around thirty further along'' is enough and stays true if the numbers are retuned.', 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('17', '2', 'during-the-diagnosis', 'During the diagnosis', 'Am I getting the same questions as everyone else?', 'No. Ally chooses each question after reading your last answer.

Two founders at the same stage will start in similar territory, but the moment your answers differ, the questions differ. You will also see the topic change as you go — you might move from questions about how you think to questions about your idea, depending on what Ally is following up.

Your stage also decides which areas Ally covers at all.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'Watched the category chip change from Founder Psychology to Idea & Validation, and the next question was chosen after the previous answer was sent.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('18', '2', 'during-the-diagnosis', 'During the diagnosis', 'Can I skip a question I don''t want to answer?', 'There is no skip button, but there is a way past.

Under the answer box there is an "I''m not sure" button. Tap it and Ally moves on to a different question.

It does not count against you and it is not saved as an answer. It is there for questions you cannot answer, or would rather not.

If a question feels wrong for your business, that is a good moment to use it.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'Pressed it. The session moved from question 307 (Founder Psychology) to 217 (Idea & Validation), and no answer row was written to the database.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('19', '2', 'during-the-diagnosis', 'During the diagnosis', 'I don''t know the answer to this. What do I put?', 'Use the "I''m not sure" button under the answer box. That is exactly what it is for.

Ally will move to a different question. Nothing is marked wrong and nothing is lost.

Please do not guess, especially with numbers. A made-up figure is worse than no answer, because Ally will treat it as real and build on it.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'Same walk as question 18.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('20', '2', 'during-the-diagnosis', 'During the diagnosis', 'Can I go back and change an answer?', 'Not during the diagnosis, sorry. There is no back button, and once an answer is sent it stays.

If you want to correct something, type the correction as your next answer. Ally reads everything you write, so saying "actually, about that last question…" does reach it.

There is one place you can edit freely: before the diagnosis starts, Ally shows you a summary of your profile answers, and everything on that screen can be changed.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis,/guided/summary}', '2026-09-05', 'Read the full diagnosis screen: the only controls are the answer box, the ''I''m not sure'' button, a microphone and send. No back or edit control exists.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('21', '2', 'during-the-diagnosis', 'During the diagnosis', 'I closed the tab. Did I lose my progress?', 'No. Your answers are saved as you go — the diagnosis screen says so at the top of the page.

When you come back, Ally shows a "Welcome back" screen with how far you got, and picks up at the next question.

You can close the tab, come back on another device, or leave it for days. Nothing is lost.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis,/guided/resume}', '2026-09-05', 'The diagnosis header reads ''your answers are saved as you go'' and the footer showed ''Saving your answer...'' on send. A session started 2026-08-25 resumed intact eleven days later.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('22', '2', 'during-the-diagnosis', 'During the diagnosis', 'Why did it ask the same thing twice?', 'It should not, and if it did, that is a fault on our side rather than anything you did.

Please answer it again if you can, and Ally will carry on. Then tell us using Report a bug on the Help page, with roughly the day and time. That helps us find it.

We have seen this happen when a diagnosis is picked up again after a long gap, and we are working on it.', 'walked', 'answered', 'true', NULL, '{/app/help}', '2026-09-05', 'Reproduced. A session last answered on 2026-08-25 re-asked the question it had already answered (question 307) when resumed.', 'BUG REPRODUCED. Session 713 held one saved answer to question 307, but current_question_id was still 307, so resuming re-asked a question the founder had already answered. It only advanced once a new answer was submitted. Worth a proper look: on resume the founder is asked to repeat themselves, which reads as the product not listening.', NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('23', '2', 'during-the-diagnosis', 'During the diagnosis', 'It asked something that doesn''t apply to my business.', 'That happens, and there is a quick way past it. Tap "I''m not sure" under the answer box and Ally moves on.

You can also just say so in your own words — for example, "we don''t have a sales team yet". Ally reads that and takes it into account.

If several questions feel wrong for your business, please send us feedback. That usually means we have your stage or your industry wrong, and we would want to know.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis,/app/feedback}', '2026-09-05', 'The answer box accepts free text alongside the ''I''m not sure'' button; its placeholder is ''Answer Ally''s question or ask anything…''.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('24', '2', 'during-the-diagnosis', 'During the diagnosis', 'How long should my answers be? Does writing more get me a better report?', 'Write as much as you naturally would. A few sentences is plenty.

Longer is not automatically better. What helps is being specific — real numbers, real examples, what actually happened. One clear sentence about a real situation is worth more than a paragraph of general description.

Short answers are fine too. If you only have one line, give the one line.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'The answer box is free text with no length guidance or limit shown. A long saved answer and a two-word one were both accepted.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('25', '2', 'during-the-diagnosis', 'During the diagnosis', 'What if I''d rather not be fully honest about something?', 'That is your choice, and nobody will know.

But it is worth knowing what happens. Ally notices when answers feel guarded, and when they do it treats the diagnosis as less certain and words your report more carefully. It is not accusing you of anything.

The report is only as good as what it is built on. If something is hard to say, "I''m not sure" is a cleaner answer than one that is not quite true.

Nothing you write here is shared with anyone.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'The seeded session-state model reads guardedness and lowers a reliability factor, which changes how the report is framed rather than what it accuses the founder of.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('26', '2', 'during-the-diagnosis', 'During the diagnosis', 'Can I answer out loud instead of typing?', 'Yes. There is a microphone button next to the answer box. Tap it and speak.

Voice works during the diagnosis on every plan.

Your words appear as text before they are sent, so you can read them back and fix anything before you answer.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'The microphone button sits inside the answer box, and the screen footer reads ''Structured diagnosis · Voice input free on every plan here''.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('27', '2', 'during-the-diagnosis', 'During the diagnosis', 'The voice transcription got my words wrong.', 'That does happen, especially with names, numbers, and Indian city or brand names.

Your words appear as text in the answer box before they are sent, so you can correct them there before answering. Please do check any numbers — a wrong revenue figure will change what Ally concludes.

If it keeps getting one particular word wrong, just type that part.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'Voice input writes into the same editable answer box, so text can be corrected before sending.', NULL, 'The claim about accuracy on Indian names is a general caution, not a measured result. If a support answer should not say that, cut the first line - the rest stands on its own.', 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('28', '2', 'during-the-diagnosis', 'During the diagnosis', 'It never asked me anything about my team or my revenue. Why not?', 'That is on purpose, not something missed.

Ally only asks about the areas that make sense for your stage. If you are still working on an idea, there is no team or revenue to examine yet, so asking would only produce guesses — and a guess treated as fact makes the report worse, not better.

At the idea stage Ally looks at you as a founder and at the idea itself. Founders further along are asked about team, revenue and operations as well.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'Stage scope is applied before questions are ranked: the earliest stage covers only Founder Readiness and Market Clarity, and no business health score is published for it.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('29', '2', 'during-the-diagnosis', 'During the diagnosis', 'Can I stop and come back tomorrow?', 'Yes, whenever you like. There is no time limit and nothing expires.

Your answers save as you go, so you can simply close the tab. When you come back, Ally shows how far you got and starts again at the next question.

Taking a break is fine. Some of these questions are worth thinking about.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis,/guided/resume}', '2026-09-05', 'A session started on 2026-08-25 was still in progress and resumable on 2026-09-05, eleven days later, with its answer intact.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('30', '2', 'during-the-diagnosis', 'During the diagnosis', 'It crashed halfway. Have I burned my one diagnosis?', 'No. Only a finished diagnosis counts.

If it stopped part-way, your answers are still saved and you can carry on from where you were. Sign in again and Ally will show you your progress.

If it will not continue, please tell us using Report a bug on the Help page and we will look at your session.', 'walked', 'answered', 'true', NULL, '{/app/help}', '2026-09-05', 'An in-progress session eleven days old was still open and resumable, and had not been counted against the account.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('31', '2', 'during-the-diagnosis', 'During the diagnosis', 'My cofounder knows the numbers. Can they answer part of it?', 'It is better if you answer it yourself.

The diagnosis is built around how you think and decide, so answers written in someone else''s words change what it finds. There is also one login per account.

The practical way is to ask your cofounder for the numbers first, then do the diagnosis yourself with those numbers next to you. Where you are still not sure of a figure, "I''m not sure" is better than a guess.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'One account, one session. Shared or multi-user access does not exist in the product today.', NULL, 'Related to the open team-account decision (questions 200, 201). This answer deliberately gives the practical workaround rather than promising anything about shared accounts.', 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('32', '2', 'during-the-diagnosis', 'During the diagnosis', 'Is Ally judging me while I answer?', 'No. Ally is not scoring you as a person, and there is no pass or fail.

It does pay attention to how you answer as well as what you say — for example, whether answers feel guarded, or whether you sound like you are under a lot of pressure. That is only used to decide how carefully to word your report and how much weight to put on it.

Nobody else sees your answers.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'The seeded psychological-state model changes report framing and a reliability figure. It produces no score about the founder as a person.', NULL, NULL, 'group-02-during-the-diagnosis.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('33', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'How does answering some questions tell you what''s actually wrong with my business?', 'Because Ally is not reading your answers one at a time. It is looking for the pattern underneath them.

Each answer is matched against a large body of real founder problems and the causes behind them. When several of your answers point the same way, that pattern narrows down to one likely cause.

That is why the questions change as you go. Each answer rules some things out, so the next question can be sharper about what is left.

The problem you came in with is the starting point, not the answer.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis}', '2026-09-05', 'Watched the live diagnosis choose each next question after the previous answer, and move between categories.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('34', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Is this based on a real framework, or something you made up?', 'It is our own framework, built deliberately rather than borrowed.

Ally looks at your business across six areas: Founder Readiness, Market Clarity, Revenue Maturity, Product & Execution, Team & Leadership, and Strategic Clarity. Underneath those sit more than a hundred smaller things it can look at.

It was built from real founder work — more than 10,000 founder case studies, and 25,000 founder problems traced back to what actually caused them.

So: made by us, but not made up.', 'walked', 'answered', 'true', NULL, '{}', '2026-09-05', 'Six pillars read from the readiness_pillars reference table. The corpus figures are the ones published on join.goxlally.ai.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('35', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Why six pillars? Why not more?', 'There are more than six things being looked at. Six is how they are grouped so you can read them.

Underneath those six sit over a hundred smaller areas. Ally works at that finer level, then rolls what it finds up into six, so your report is something you can actually take in.

If we showed you a hundred scores you would have data, not clarity. Six areas that each mean something are more useful than a hundred that blur together.', 'policy', 'answered', 'true', NULL, '{}', '2026-09-05', 'Agreed disclosure position: name the six, describe what sits beneath only as ''more than a hundred'', never the internal counts.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('36', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Why those six, and not the things I actually worry about — pricing, hiring, funding?', 'Those are all in there. They sit inside the six.

Pricing is part of Revenue Maturity, along with your sales process and your unit economics. Hiring sits in Team & Leadership. Funding sits in Strategic Clarity, with your goals and how you make trade-offs.

The six are groups, not a list of topics. They are grouped by what causes what, rather than by department — because a pricing problem is often really a market clarity problem wearing different clothes.', 'walked', 'answered', 'true', NULL, '{}', '2026-09-05', 'Read each pillar''s band descriptions: pricing and unit economics sit under Revenue Maturity, delegation and hiring under Team & Leadership, capital strategy under Strategic Clarity.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('37', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Who decided what a "healthy" business looks like?', 'We did, and it comes from patterns in real founder cases rather than from opinion.

Each of the six areas has four levels: Critical Gap, Needs Attention, Developing, and Strong. Each level has a written description of what a business at that level actually looks like — for example, Strong in Revenue Maturity means pricing on value, tracking pipeline, and knowing your unit economics.

Those descriptions came from thousands of real founder cases, not from a textbook idea of a perfect company.

The six are also not weighted equally. Some matter more to whether a business survives.', 'walked', 'answered', 'true', NULL, '{}', '2026-09-05', 'Read all four band descriptions for all six pillars, and their differing weights.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('38', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Am I being compared against other founders, or only against myself?', 'Against a pattern, not against a leaderboard.

Your answers are matched against a large body of real founder cases, to work out what your situation most resembles and what usually causes it. That is where the read comes from.

But you are not ranked against other founders, no one else''s results change yours, and nobody is told how you compare.

Your stage matters too. A founder still working on an idea is not measured against one with a team and revenue.', 'walked', 'answered', 'true', NULL, '{}', '2026-09-05', 'Scoring runs against seeded reference thresholds per stage and industry. No cross-founder ranking exists anywhere in the product.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('39', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'What is my business health measured out of, and how is it worked out?', 'Each of the six areas is scored out of 100, and each score lands in one of four levels: Critical Gap, Needs Attention, Developing, or Strong.

Your overall reading combines those six, but not evenly. The areas that matter most to whether a business survives count for more.

Only the areas Ally actually asked you about are included. If your stage meant an area was never in scope, it is left out rather than guessed at.', 'walked', 'answered', 'true', NULL, '{}', '2026-09-05', 'Band ranges read from readiness_pillars: 0-35 Critical Gap, 36-55 Needs Attention, 56-75 Developing, 76-100 Strong. Weights differ per pillar and sum to 100. Out-of-scope pillars are excluded and the remaining weights renormalised.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('40', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'My report has no health reading at all. Is something missing?', 'No, nothing is missing. This happens on purpose at the earliest stage.

If you are still working on an idea, there is not enough business yet to score fairly. Ally would be scoring you on things that do not exist, and a number like that would look precise while meaning nothing.

Instead you get a read on you as a founder, and on the idea itself. That is the honest thing to give you at this point.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'Stage scope marks the earliest stage as not emitting a business health score at all, because only two of the six pillars are in scope there.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('41', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Why do I get a word like "Developing" instead of a number?', 'Because the word is more honest than a number would be.

There are four levels: Critical Gap, Needs Attention, Developing, and Strong. Developing means you are reasonably solid in that area — some gaps and blind spots, but nothing blocking you.

A number invites you to chase it. Going from 61 to 64 feels like progress but usually means nothing real. Moving from Developing to Strong is a change you would actually feel in the business.', 'walked', 'answered', 'true', NULL, '{/app/business-dna}', '2026-09-05', 'The four band names and their ranges are the founder-facing output; raw scores are deliberately not shown.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('42', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Why does my report look different from another founder''s?', 'Because it is built for your situation, not printed from a template.

Four parts are always there: your Founder DNA, your Business DNA, the root cause, and your priority actions. Everything else depends on what Ally found.

If Ally picked up that you are under real strain, your report opens differently — it starts with that before it talks about the business, and it offers a first step for you rather than a list of business tasks.

Your stage changes it too, because that decides which areas were examined at all.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'Compared seven real reports. Four headings appear in all of them; a high-distress report opened with ''Before we begin'' and ''A first step for you'' and carried seven sections, while a stable-state report carried ten.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('43', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'How much of this was written for me, and how much is a template?', 'The words are written for you, from your answers.

The structure is shared — every report covers your Founder DNA, your Business DNA, the root cause, and your next actions. What goes inside those sections is built from what you said and what Ally worked out from it.

Which sections you get is not fixed either. Reports genuinely differ in shape depending on what was found.

If you ever read something that feels like it could be about anyone, please tell us. That would be a fault worth knowing about.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'Seven real reports carried between seven and ten sections, in different orders, with different section sets.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('44', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Did an AI write my report, or did a person?', 'AI wrote it, and no person read it before you did.

What it is allowed to say is not open-ended, though. It works only from the answers you gave and what our framework found in them, and it is not allowed to invent findings, scores or sources that are not there.

If you want a person involved, you can book a discovery call and talk it through with someone.', 'walked', 'answered', 'true', NULL, '{/app/discovery-call}', '2026-09-05', 'The report is generated server-side with no human review step anywhere in the path. The grounding rules forbid inventing findings, scores or sources.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('45', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Which AI is behind Ally? Is this just ChatGPT?', 'We do not name the technology we use. That is a deliberate choice, not us being cagey.

The honest answer to "is this just ChatGPT" is no — but not because of which AI it is. A general chatbot answers whatever you ask it. Ally works through a fixed method: your Founder DNA, then your Business DNA, then the cause sitting underneath both, using a large body of real founder cases as its reference.

The method is what makes it different, not the engine.', 'policy', 'answered', 'true', NULL, '{}', '2026-09-05', 'Agreed disclosure position: never name the model or vendor in any founder-facing surface.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('46', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Does Ally ever just guess?', 'It is not supposed to, and it is built so that it cannot invent things.

Ally can only work from what you told it and what its framework found in that. If it does not have something, the rule is to leave it out rather than fill it in. That is why a section is sometimes missing from a report — a gap is more honest than a guess.

What it does do is infer. If several of your answers point the same way, it will name that pattern even though you never said it directly. That is a conclusion, not a guess, and you are free to disagree with it.', 'walked', 'answered', 'true', NULL, '{}', '2026-09-05', 'The generator omits a section outright when it has no value for it rather than narrating around the gap, and the grounding prompt forbids inventing findings, scores, sources or advice.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('47', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Will Ally tell me when it isn''t sure?', 'Yes, and it says so on your report.

Next to the finding, Ally states how sure it is in a word: High, Moderate, or Early. It is deliberately a word and not a percentage — a number invites you to read it as a mark out of 100, when what it really describes is how much evidence there was.

The wording changes too. Where Ally is less certain, findings are put as possibilities and next steps are offered as things to try rather than things to do.

And if a conclusion feels wrong to you, say so. Nothing in the report is beyond question.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'A real report showed ''Ally''s finding · High confidence''. Bands are High (>=75), Moderate (>=50), Early (below 50). Percentages are suppressed by design.', NULL, 'CORRECTED 2026-09-05. An earlier draft said Ally does not show confidence at all. That was wrong: it is shown, as a band. What is suppressed is the numeric percentage, not the confidence itself.', 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('48', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'What is "a note on certainty" doing in my report?', 'It appears when Ally is less sure than usual, and wants to say so rather than let you assume otherwise.

That usually means there was less to go on — a shorter conversation, or answers that were understandably held back. When confidence is low, this note opens the report instead of being buried at the end.

It is not a warning that the report is wrong. It is a note about how firmly to hold it. Treat the findings as a strong starting point rather than a verdict, and if something rings true, act on it.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'The report builder opens a low-confidence report with this section, which is why it did not appear in the sampled reports - none of them was low-confidence.', NULL, 'CORRECTED 2026-09-05. An earlier draft flagged this section as possibly unreachable because it appeared in none of seven sampled reports. It is reachable: it is the opening section of a LOW_CONFIDENCE report, and the sample simply contained none.', 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('49', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'My report says things I never told it. Where did that come from?', 'From patterns across your answers, rather than from any one thing you said.

If three separate answers all point the same way, Ally will name that pattern even though you never put it in those words. That is much of the value — it says the thing you have not said yet.

It is not allowed to invent facts about your business. Numbers, names and events come only from you.

If something genuinely does not match your business, that is worth telling us.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/feedback}', '2026-09-05', 'The diagnosis maps answers to seeded root causes and behaviour patterns; the narrator is grounded and forbidden from inventing findings.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('50', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'What''s in "what this is based on"?', 'It is Ally showing its working.

That section sets out what the findings were drawn from — the parts of your conversation, and the patterns they matched. It is there so a conclusion is not simply asserted at you.

Not every report has it. When it is missing, that is because there was not enough to show, not because anything was hidden.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', '''What this is based on'' appeared in one of the seven sampled reports, confirming it is conditional rather than standard.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('51', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'How did you decide what stage I''m at? Can that be wrong?', 'It comes from what you told us. You choose your stage yourself when you build your profile, near the start.

There are eight stages, from working on an idea through to exit.

And yes, it can be wrong — usually because the choice was made quickly. It matters more than it looks, because your stage decides which areas Ally asks about and how many questions you get.

If it looks wrong on your report, please tell us and we will look at it with you.', 'walked', 'answered', 'true', NULL, '{/guided/profile,/app/help}', '2026-09-05', 'Entrepreneurial stage is the second field in the profile build, chosen by the founder. founder_stages holds eight stages, from Ideation to Exit.', NULL, 'Deliberately does not tell the founder to change it in Profile. Whether stage can be changed after a report exists is question 4, still open with the team.', 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('52', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Why is my industry one of only four options? Mine isn''t there.', 'The four are broad on purpose: Technology & SaaS, Services & Consulting, Manufacturing & D2C, and Social Impact & NGO.

They are not meant to describe your business exactly. They are there to set expectations — what normal margins look like, how long sales usually take, what growth tends to look like. Most businesses sit reasonably inside one of the four for that purpose.

Pick whichever is closest. The detail about what you actually do comes from your own answers, and that is what the diagnosis really runs on.', 'walked', 'answered', 'true', NULL, '{/guided/profile}', '2026-09-05', 'Read the four industries from the industries table, and the per-industry, per-stage threshold table they feed.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('53', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'What is a red flag, and what sets one off?', 'A red flag means one of the six areas came out low enough that it is probably holding the others back.

Each area has a line it needs to stay above. Fall below it and Ally treats that area as the thing to deal with first, because work elsewhere tends not to stick while it is unresolved.

It is not a judgement on you. It is Ally telling you where to start.', 'walked', 'answered', 'true', NULL, '{/app/business-dna}', '2026-09-05', 'Each pillar carries its own red-flag threshold in readiness_pillars — 35 for five of them, 40 for Revenue Maturity.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('54', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'One area is flagged but the report barely talks about it. Why?', 'Because the report is built around the one thing most worth fixing first, not around everything that is imperfect.

If an area is flagged but only mentioned briefly, it usually means Ally traced it back to something else. The flagged area is a symptom of the root cause it did write about, so fixing the cause tends to move it on its own.

If you would rather work on the flagged area directly, that is a fair thing to raise on a discovery call.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/discovery-call}', '2026-09-05', 'The diagnosis converges on one root cause and the report is written around it; other flagged pillars appear as supporting detail rather than separate narratives.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('55', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Why does the report talk about me before it talks about the business?', 'Because that is the order the diagnosis works in, and often the order the problem works in too.

Ally starts with how you decide and operate, then looks at the business through that. A business problem that keeps coming back is often held in place by a habit of the founder — so naming that first makes the business section land properly.

If Ally picked up that you are under real strain, it will put that even further forward, before anything about the business at all.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'Every sampled report placed Founder DNA before Business DNA. High-distress reports opened with ''Before we begin'' and ''A first step for you'' ahead of both.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('56', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Why is there a note about my psychological state? I didn''t ask for that.', 'It is a fair thing to be surprised by, so here is what it is.

That section appears when Ally noticed real strain in the way you answered — pressure, exhaustion, or pulling back. It is there because business advice given to someone running on empty usually does not get acted on.

It is about how you are right now, not about who you are. It is not a diagnosis, and it is not on any record.

If it does not match how you feel, please say so. It is a read from one conversation, and it can be wrong.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/feedback}', '2026-09-05', 'The section is driven by the seeded psychological-state model, which reads signals in the answers and is what shifts the report''s opening under distress.', NULL, 'Reports generated before late August carry the internal heading ''Section H — Psychological State Note''. Newer ones use ''Before the business — how you''re doing''. Because a report is frozen when it is made, older founders keep the old heading. Not a live bug, but a support agent may see the old wording quoted back at them.', 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('57', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'Are you diagnosing my mental health?', 'No. We are not qualified to, and Ally is not trying to.

What it does is much smaller: it notices how you answered — whether you sounded stretched, or held back — and uses that to decide how carefully to word your report and how much weight to put on it. It produces no mental health assessment of any kind.

If something in your report worries you, please talk to someone qualified. And if you are having a genuinely hard time, please reach out to a real person. That matters far more than any of this.', 'policy', 'answered', 'true', NULL, '{}', '2026-09-05', 'Agreed position: the psychological signal is a session-reliability measure that changes report framing, not a clinical assessment.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('58', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'What happens to my answers after the report? Are they reused?', 'They stay in your account, and they are used to help you.

Your answers are what your report was built from, and Ally draws on them when you talk to it later, so you do not have to explain your business again every time.

They are not shared with other founders and they are not sold.

You can download everything we hold at any time from Profile → Privacy Center, or ask us to delete it.', 'walked', 'answered', 'true', NULL, '{/app/profile}', '2026-09-05', 'Diagnosis answers appear in the data export as their own section, and are available to chat as founder memory.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('59', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'If I did this again tomorrow, would I get the same answer?', 'Broadly yes, but not word for word.

The method is fixed and your situation would be the same, so the root cause it lands on should be the same. The wording would differ, and if you answered a question differently, Ally would follow that thread instead.

A big change usually means something real changed — you were more open the second time, or something in the business moved.

In practice this is not something you can test: there is one diagnosis per account.', 'walked', 'answered', 'true', NULL, '{}', '2026-09-05', 'Question selection follows the previous answer, so a different answer changes the path. The lifetime limit is one completed diagnosis per account on every plan.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('60', '3', 'how-ally-reaches-its-answer', 'How Ally reaches its answer', 'How accurate is this? Has it been tested against anything?', 'Here is the honest answer. We have not published an accuracy figure, and we would rather say so than give you a number that sounds impressive and means nothing.

What we can tell you is what it is built on: more than 10,000 founder case studies and 25,000 founder problems traced back to their causes, across more than a hundred areas.

The better test is whether the root cause it names sounds true when you read it. If it does not, please tell us. That is far more useful to us than a score.', 'policy', 'answered', 'true', NULL, '{/app/feedback}', '2026-09-05', 'Agreed position: no accuracy percentage may be claimed; describe the method''s basis using only the published figures.', NULL, NULL, 'group-03-how-ally-reaches-its-answer.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('61', '4', 'reading-the-report', 'Reading the report', 'What am I supposed to do with this report?', 'Read it once, then pick one thing.

The most important part is the root cause — the one thing Ally thinks is really holding you back. Everything else in the report supports it.

Under that you will find your priority actions. Start with the first one. They are in that order on purpose, because the first usually makes the next one easier.

At the bottom there are two buttons. "See your next steps" opens your action list, and "Discuss this with Ally" lets you talk any of it through.

You do not need to act on everything. One real change beats six half-changes.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/next-steps,/app/ally-chat}', '2026-09-05', 'Both buttons confirmed at the foot of a real report.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('62', '4', 'reading-the-report', 'Reading the report', 'Why is my confidence score low? Is that bad?', 'Not bad, but worth knowing.

Next to the finding, Ally says how sure it is: High, Moderate, or Early. It is a word rather than a percentage, because a number invites you to read it as a mark out of 100.

"Early" usually means there was less to go on — a shorter conversation, or an area Ally could not test properly. It does not mean the finding is wrong. It means treat it as a strong lead rather than a settled fact.

Either way the test is the same. If it rings true, act on it. If it does not, please tell us.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/feedback}', '2026-09-05', 'A real report showed ''Ally''s finding · High confidence'' as a word. Bands are High/Moderate/Early; percentages are deliberately suppressed.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('63', '4', 'reading-the-report', 'Reading the report', 'What does "root cause" actually mean here?', 'It is the thing sitting underneath the problem you came in with.

Most founders arrive with a symptom — sales are slow, the team is not delivering, there is never enough time. Those are real, but they are usually produced by something else, and treating the symptom alone does not hold.

The root cause is Ally''s best answer to "what is actually causing this?"

It is written in plain words and given a name, so you can argue with it. If it does not sound like your business, that is worth telling us.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'The Root cause section names the finding in plain language and states the symptom the founder came in with alongside it.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('64', '4', 'reading-the-report', 'Reading the report', 'My report looks thin — is that all of it?', NULL, 'policy', 'open_for_team', 'false', 'Open decision: do we defend shorter reports or fix them? An answer written before that is decided would either excuse a real product problem or admit one we have not agreed to admit.', '{/app/report}', NULL, NULL, NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('65', '4', 'reading-the-report', 'Reading the report', 'A section says it isn''t filled in yet. Is my report incomplete?', 'No, your report is complete. That line is us being straight with you.

Some sections are only written when there is something real to put in them. Rather than pad one out, Ally leaves it out and tells you that it did.

The one most often missing is expected impact — a projection of what should change once you act. We would rather leave it blank than give you a number we made up.

Everything that matters is there: your root cause, and what to do about it.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', '''expected_impact'' is the section listed as unpopulated on generated reports.', 'CHECK WHERE THIS LINE ACTUALLY SHOWS. The ''Not generated for this report: ...'' line is rendered by the React fallback view, but did not appear inside the server-built report document that founders actually see. So a founder may never be shown which section was skipped — which is the opposite of the honesty the line was written for. Worth confirming and, if true, adding it to the document builder.', NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('66', '4', 'reading-the-report', 'Reading the report', 'What''s the difference between "priority actions" and "how to sequence this"?', 'Priority actions are what to do. Sequencing is what order to do it in.

The actions are the moves themselves, usually three, chosen because they deal with the root cause rather than the symptom.

The sequencing section explains why that order and not another. Often the first action is not the biggest one — it is the one that makes the rest possible.

Not every report has a sequencing section. When it is missing, the actions are still listed in priority order, so start at the top.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/next-steps}', '2026-09-05', '''Priority actions'' appeared in every report sampled; ''How to sequence this'' in only one, confirming it is conditional.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('67', '4', 'reading-the-report', 'Reading the report', 'Why does it repeat things I already told it?', 'Because it shows you what it heard before it tells you what it thinks.

Your report includes a part that reflects your own words back to you. It can look like repetition, but it is there so you can check Ally understood you before you take its conclusions seriously.

If that part does not match what you meant, then everything after it is built on a misunderstanding. Much better to catch that on the first page than at the end.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'A real report carried a ''What we heard'' section reflecting the founder''s stated symptom back before the finding.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('68', '4', 'reading-the-report', 'Reading the report', 'It named a problem I already fixed.', 'That can happen, and it is usually about timing.

Your report is a picture of the moment you did the diagnosis. It does not update afterwards, so anything you fixed the week after will not be in it.

It is also worth reading twice before dismissing it. Sometimes what you fixed was the symptom, and Ally is pointing at what was causing it.

If it is genuinely out of date, please tell us. And if you would like to talk it through, you can book a discovery call.', 'walked', 'answered', 'true', NULL, '{/app/feedback,/app/discovery-call}', '2026-09-05', 'The report is generated once and stored as a frozen snapshot; nothing recomputes it.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('69', '4', 'reading-the-report', 'Reading the report', 'Does the report update over time, or is it frozen from the day I did it?', 'It is frozen, and that is on purpose.

Your report is built from one diagnosis and stays exactly as it was on the day it was made. It even carries the month in its header.

We do it this way because a report that quietly changes is not something you can act on. You would never know whether you were making progress or the goalposts had moved.

Think of it as a photograph, not a dashboard. The parts of Ally that do keep moving are your next steps, your goals, and Plan Your Day.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/next-steps,/app/plan}', '2026-09-05', 'The report header carries a month stamp; the narrative is stored as a snapshot at generation time and never regenerated.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('70', '4', 'reading-the-report', 'Reading the report', 'My business has changed a lot since. Is the report worthless now?', 'Not worthless, but read it with the date in mind.

The facts in it — your numbers, your team, your stage — are from the day you did it, and those go out of date.

The root cause usually does not, at least not quickly. Patterns in how a founder decides, and how a business runs, tend to outlast a quarter. Plenty of founders find the same cause is still there, just wearing different clothes.

Running the diagnosis again is not available yet. It is something we intend to offer once your business stage changes.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'Agreed position: one diagnosis per account today; re-diagnosis at a stage change is intended but not built or sold.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('71', '4', 'reading-the-report', 'Reading the report', 'Where do I find my report again later?', 'It is always in the sidebar, under Report.

That link appears once your first report exists, and every report you run is kept there. Nothing expires.

On the report itself there are two buttons at the top: Download PDF saves a copy you can keep, and Share creates a link.

If you cannot see Report in your sidebar, it means no report has been generated yet.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'Sidebar entry ''Report'' is gated on a report existing. Download PDF and Share confirmed on the live report document.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('72', '4', 'reading-the-report', 'Reading the report', 'Can I get someone — or Ally — to walk me through it line by line?', 'Yes, both.

At the bottom of your report there is a "Discuss this with Ally" button. That opens a chat where Ally already knows what is in your report, so you can ask about any part of it — what a section means, or how it reached a conclusion.

If you would rather talk to a person, you can book a discovery call.

There is also a "Was this report useful?" question at the end of the report. It takes seconds to answer and it genuinely reaches us.', 'walked', 'answered', 'true', NULL, '{/app/ally-chat,/app/discovery-call}', '2026-09-05', 'Both buttons and the feedback prompt confirmed on a real report page.', NULL, NULL, 'group-04-reading-the-report.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('73', '5', 'disagreeing-with-it', 'Disagreeing with it', 'I don''t agree with what it says about me.', 'That is a fair thing to say, and we would much rather you said it to us than closed the tab.

Ally works from one conversation. It can read you wrongly, especially if you were short of time or holding something back that day.

Two things help. At the end of your report there is "Was this report useful?" — say there what did not fit. And "Discuss this with Ally" lets you push back directly and ask why it reached that conclusion.

If it still feels wrong, tell us on the Feedback page. A founder saying "this is not me" is one of the most useful things we get.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/ally-chat,/app/feedback}', '2026-09-05', 'Confirmed the rating prompt at the foot of a real report, the ''Discuss this with Ally'' button, and that feedback reaches the admin queue.', NULL, 'The wider question of how firmly we defend a finding is still open with the team (listed against question 64). This answer deliberately takes no position on that — it only gives the founder real routes.', 'group-05-disagreeing-with-it.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('74', '5', 'disagreeing-with-it', 'Disagreeing with it', 'This is factually wrong about my business. Fix it.', 'There are two different things here, and they take different routes.

If a fact about you is wrong — your name, your stage, something in your profile — go to Profile, then Privacy Center, and use "Request data correction". That reaches a person.

If it is the finding you disagree with rather than a fact, that is not a correction, it is a disagreement — and it is just as welcome. Use "Was this report useful?" at the end of your report, or the Feedback page.

One thing to know: your report is fixed at the day it was made, so a correction will not rewrite it.', 'walked', 'answered', 'true', NULL, '{/app/profile,/app/report,/app/feedback}', '2026-09-05', '''Request data correction'' is one of the seven Privacy Center actions and creates a reviewed request. Reports are stored as frozen snapshots and are not regenerated.', NULL, NULL, 'group-05-disagreeing-with-it.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('75', '5', 'disagreeing-with-it', 'Disagreeing with it', 'It said something harsh. Is that deliberate?', 'Direct, yes. Harsh, no — and if it landed as harsh, we would want to know.

Ally is built to say the real thing rather than the comfortable thing. A diagnosis that avoids the difficult part is not much use to anyone.

But there is a line between direct and unkind, and Ally is meant to stay on the right side of it. If something felt like a judgement on you rather than a read of your situation, please tell us on the Feedback page — "Something confused me" or "Something else" both work.

It is describing a moment, not deciding who you are.', 'walked', 'answered', 'true', NULL, '{/app/feedback}', '2026-09-05', 'Feedback topics confirmed on the Feedback page. Report tone shifts by session state, and under distress the report leads with acknowledgement before any business content.', NULL, NULL, 'group-05-disagreeing-with-it.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('76', '5', 'disagreeing-with-it', 'Disagreeing with it', 'Can I get a second opinion from an actual human?', 'Yes. That is what a discovery call is for.

You can book one from Help & Support, or from the Discovery call page. It is a conversation with someone from our team who can go through your report with you and take your disagreement seriously.

How many calls are included depends on your plan.

If you only want a quick answer rather than a call, the Feedback page or a message to support works too, and a person reads those.', 'walked', 'answered', 'true', NULL, '{/app/discovery-call,/app/help,/app/feedback}', '2026-09-05', 'Booking is reachable from Help & Support and from the Discovery call page. Call allowances deliberately not stated here — they change with the new pricing.', NULL, NULL, 'group-05-disagreeing-with-it.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('77', '5', 'disagreeing-with-it', 'Disagreeing with it', 'Who do I complain to if the report is bad?', 'Us, directly — and it does reach a person.

The quickest way is Help & Support, then "Message support". You can also use the Feedback page and pick "Something else".

We reply by email, usually within one working day. Our hours are Monday to Friday, 9am to 6pm IST.

Please include what the report said and what you think is wrong. That is far more useful to us than a rating, and complaints about findings get read carefully — they are how we learn the method is off.', 'walked', 'answered', 'true', NULL, '{/app/help,/app/feedback}', '2026-09-05', 'Help & Support lists info@goxl.in, Mon-Fri 9am-6pm IST, and states the aim of a reply within one working day. Support messages post through the same pipeline as feedback and are tagged so the team can tell them apart.', NULL, NULL, 'group-05-disagreeing-with-it.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('78', '5', 'disagreeing-with-it', 'Disagreeing with it', 'I rushed my answers and the report shows it. Can I redo it?', 'Not at the moment, and we know that is frustrating.

There is one diagnosis per account, so it cannot be run again today. Being able to redo it when your business stage changes is something we intend to add, but it is not available yet.

What you can do now is open "Discuss this with Ally" from your report and give it the fuller answer you did not have time for. Ally will work with what you tell it there, even though the report itself will not change.

If the report is badly off because of it, contact support and we will look at it with you.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/ally-chat,/app/help}', '2026-09-05', 'Agreed position: one completed diagnosis per account on every plan; re-diagnosis at a stage change is intended but unbuilt. Chat carries the founder''s report and memory as context.', NULL, NULL, 'group-05-disagreeing-with-it.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('79', '6', 'getting-the-report-out', 'Getting the report out', 'Can I download or share this?', 'Yes, both. The buttons are at the top of your report.

Download PDF saves a copy to your device. It is yours to keep, and it looks the same as the report on screen.

Share creates a link and copies it to your clipboard. Anyone you send that link to can open the report without signing in.

There is also a full export of everything Ally holds about you in Profile, then Privacy Center, if it is the data you want rather than the document.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/profile}', '2026-09-05', 'Both buttons confirmed on a real report document. The share route requires no authentication.', NULL, NULL, 'group-06-getting-the-report-out.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('80', '6', 'getting-the-report-out', 'Getting the report out', 'Does the PDF look the same as what I see on screen?', 'Yes. It is the same document, printed rather than rebuilt.

The PDF is made by rendering the exact same page, with the same layout, colours and fonts. The fonts are built into the file, so it looks right on whatever machine you open it on.

If the PDF is not ready the moment you ask for it, we will say so and prepare it, rather than hand you a rough version that looks finished. A missing file is easy to fix. A wrong one that looks fine is not.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'The PDF is produced by a headless-Chromium sidecar from the same print HTML, with the document''s own page CSS, backgrounds and base64-embedded fonts. The endpoint refuses rather than substituting a different renderer''s output.', NULL, NULL, 'group-06-getting-the-report-out.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('81', '6', 'getting-the-report-out', 'Getting the report out', 'If I share the link, can anyone open it?', 'Yes — and that is worth being clear about.

The link does not ask anyone to sign in. Whoever has it can read your report. The address itself is long and random, so nobody will find it by guessing, but it will work for anyone you send it to, and for anyone they pass it on to.

It stops working after 30 days.

One thing to know: there is currently no way to switch a link off yourself before then. If you need one cancelled early, contact support and we will do it for you.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/help}', '2026-09-05', 'The shared-report endpoints take no auth dependency. Tokens are 24 random bytes. TTL is 30 days. Revocation exists in the API but has no caller anywhere in the frontend.', 'PRODUCT GAP. Revoking a share is API-only. A founder who shares their diagnosis cannot un-share it from the product. This answer is honest about that and routes to support, but the button is small work and worth adding — the content being shared is a personal analysis of the founder, not a marketing page.', NULL, 'group-06-getting-the-report-out.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('82', '6', 'getting-the-report-out', 'Getting the report out', 'Can I send this to my investor or my board?', 'Yes, and the share link is made for exactly that.

Use Share to create a link, or Download PDF if you would rather attach a file. Investors usually prefer the PDF.

Two things worth thinking about first. The report is honest about weaknesses as well as strengths, so read it through before you send it. And the Founder DNA part is personal — some founders share the business sections and keep that one back.

A shared link works for 30 days, and anyone who has it can open it.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'Share and Download PDF both confirmed. Report sections confirmed to include a personal Founder DNA section alongside the business analysis.', NULL, NULL, 'group-06-getting-the-report-out.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('83', '6', 'getting-the-report-out', 'Getting the report out', 'Can I get it as something I can edit?', 'Not directly, sorry. The report comes as a PDF, which is fixed.

If you want the words in your own document, you can copy them from the report on screen and paste them wherever you like.

If it is the underlying information you want rather than the document, go to Profile, then Privacy Center, and use "Download my data". That gives you everything as a data file.

There is no Word or Google Docs version at the moment.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/profile}', '2026-09-05', 'PDF is the only document export. The privacy export produces JSON. No document-format conversion exists anywhere in the product.', NULL, NULL, 'group-06-getting-the-report-out.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('84', '6', 'getting-the-report-out', 'Getting the report out', 'Can I print it?', 'Yes. The simplest way is to use Download PDF and print that — the layout is built for paper, so the pages break in sensible places.

You can also print straight from your browser while you are looking at the report.

One thing to keep in mind: if you are printing it to give to someone, the report includes personal parts about you as a founder, not only the business.', 'walked', 'answered', 'true', NULL, '{/app/report}', '2026-09-05', 'The print HTML carries its own @page CSS, which is what the PDF renderer honours, so paper layout is deliberate rather than incidental.', NULL, NULL, 'group-06-getting-the-report-out.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('85', '7', 'doing-it-again', 'Doing it again', 'Why can''t I do another diagnosis?', 'There is one full diagnosis per account at the moment.

It is not meant as a monthly check-up. It goes deep once, builds your Founder DNA and your Business DNA, and finds the one cause sitting underneath. Running it again a few weeks later would mostly tell you the same thing, because the patterns it looks at do not move that fast.

We do intend to let you run it again when your business stage changes. That is not built yet.

If you have a real reason to need a second one now, please contact support. We look at those case by case.', 'walked', 'answered', 'true', NULL, '{/app/help}', '2026-09-05', 'The lifetime limit is one completed diagnosis on every tier. An admin reset exists and is used case by case.', NULL, NULL, 'group-07-doing-it-again.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('86', '7', 'doing-it-again', 'Doing it again', 'I''m paying for Pro. Surely I get another one?', 'No — and we would rather say so plainly than let you find out later. Every plan includes one diagnosis, including the highest one.

What paying gives you is everything that keeps working after the report: your Founder DNA and Business DNA pages, your next steps, and Ally to talk to every day. It does not buy more diagnoses.

If that is not what you understood when you paid, please contact support and tell us. That is a fair complaint and we would want to hear it.', 'policy', 'answered', 'true', NULL, '{/app/help,/app/billing}', '2026-09-05', 'The lifetime limit is identical across every tier. Agreed position: say so plainly rather than implying an exception.', NULL, 'Deliberately names no tier. The question says ''Pro'', which is the current catalog name, but tier names and prices change with the Rs 199 entry plan. This answer survives that.', 'group-07-doing-it-again.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('87', '7', 'doing-it-again', 'Doing it again', 'Can I just pay for one more?', 'Not as something you can buy, no. There is no add-on for a second diagnosis on any plan.

But it is not a flat no either. If your situation has genuinely changed — you pivoted, you raised, the business is a different shape now — contact support and tell us what changed. We look at these one at a time, and we can reset it where it makes sense.

If we do, your first report stays. You do not lose it.', 'walked', 'answered', 'true', NULL, '{/app/help}', '2026-09-05', 'No purchasable add-on exists in the catalog. The admin reset clears only the counter and the lock; the existing report row is untouched, so the old report survives a reset.', NULL, NULL, 'group-07-doing-it-again.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('88', '7', 'doing-it-again', 'Doing it again', 'How am I supposed to tell whether anything improved?', 'Not by running the diagnosis again, since there is only one. What you track instead is what you did about it.

Your report gives you priority actions. Those become your next steps, and Ally keeps count of how many you have finished against how many are still open. That count is the honest measure — the report told you what to change, and this tells you whether you changed it.

Goals and Plan Your Day work the same way. Set the thing, then look back at what actually got done.

Your report itself does not move. It is the baseline you are measuring against.', 'walked', 'answered', 'true', NULL, '{/app/next-steps,/app/goals,/app/plan}', '2026-09-05', 'The dashboard tracks actions completed against actions open, plus counts of sessions, conversations and reports. No metric re-scores the founder over time.', NULL, NULL, 'group-07-doing-it-again.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('89', '7', 'doing-it-again', 'Doing it again', 'Can I redo one part instead of the whole thing?', 'Not at the moment, sorry. The diagnosis works as one piece — your Founder DNA shapes how the business answers are read, so redoing one part on its own would not really hold together.

If a particular answer was wrong or rushed, the most useful thing is to open "Discuss this with Ally" from your report and tell it there. Ally will work with the fuller picture, even though the report itself stays as it was.

And if a fact in your profile is simply wrong, you can ask us to correct that in Profile, then Privacy Center.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/ally-chat,/app/profile}', '2026-09-05', 'No partial re-run exists — the only reset is the whole-diagnosis admin action. Founder DNA feeds the business scoring, so the parts are not independent.', NULL, NULL, 'group-07-doing-it-again.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('90', '8', 'talking-to-ally', 'Talking to Ally', 'Can Ally read a file if I upload it? What kinds?', 'Yes, for documents. You can attach a file in the chat and Ally will read it.

It reads PDFs, Word documents, plain text, Markdown and CSV files.

Images are the exception. You can attach a photo or a screenshot and it will upload, but Ally cannot read what is inside it yet — so if your numbers are in a screenshot, please paste them as text instead. Scanned PDFs are the same: if there is no real text in the file, Ally cannot read it.

With a long document Ally reads a portion rather than every page, so it helps to say which part you care about.', 'walked', 'answered', 'true', NULL, '{/app/ally-chat}', '2026-09-05', 'TESTED END TO END. Uploaded a CSV and asked Ally to quote its contents: it returned both months and both revenue figures exactly. Uploaded a PNG containing two plain numbers: it could not read them.', 'CORRECTED, AND THE PRODUCT FIXED. An earlier draft listed images as supported because the mime-type list accepts them. They upload (201) but cannot be read: LLMMessage.content is a plain string, so the provider layer has no way to carry an image at all. The vision builder was assembling media blocks that were then dropped, while the prompt told the model the file was ''attached for you to look at'' — so Ally claimed to have read images it never saw. That is the bank''s question 217. Media is now off by default and Ally says plainly that it cannot read the file. Turn it back on in the same change that makes the transport multimodal.', NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('91', '8', 'talking-to-ally', 'Talking to Ally', 'Can it build me a pitch deck?', 'It can help you write one, but it cannot hand you a file.

Ally will work through the story with you — what to lead with, what your one-line problem is, which numbers matter, what an investor will ask. You can then copy that into your own slides.

What it cannot do is produce a PowerPoint or a Google Slides deck for you to download. There is no file export from chat.

The one document Ally does produce is your report, which you can download as a PDF.', 'walked', 'answered', 'true', NULL, '{/app/ally-chat,/app/report}', '2026-09-05', 'Chat returns text only. The report PDF is the single document export anywhere in the product.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('92', '8', 'talking-to-ally', 'Talking to Ally', 'Does Ally remember what I told it last week?', 'Yes. Ally keeps a memory of you and brings it into every conversation.

That includes your diagnosis, what came out of it, and things you have told it since. So you do not have to explain your business again each time you open the chat.

It is not a word-for-word transcript of everything you have ever said. It is a summary of what matters, which is why it sometimes remembers the point you made rather than the exact sentence.

If it has remembered something wrongly, just tell it in the chat.', 'walked', 'answered', 'true', NULL, '{/app/ally-chat}', '2026-09-05', 'Chat context includes a founder memory summary alongside the diagnosis, retrieved knowledge and a diagnostic map.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('93', '8', 'talking-to-ally', 'Talking to Ally', 'Why did Ally stop replying?', 'Almost always one of three things.

You have used your chat allowance for today. It resets, and you can carry on tomorrow.

You have used up your allowance for the month. Your billing page shows what is left.

Or AI processing is paused on your account — that only happens if you turned it off yourself in Profile, then Privacy Center. There is a banner there with a Resume button.

If it is none of those and Ally simply stopped mid-answer, that is a fault. Please send it to support so we can look.', 'walked', 'answered', 'true', NULL, '{/app/billing,/app/profile,/app/help}', '2026-09-05', 'Three distinct refusals exist: a daily token ceiling, an exhausted credit balance, and a processing-restricted block. The restricted case returns a clear message naming the Privacy Center.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('94', '8', 'talking-to-ally', 'Talking to Ally', 'Can I delete a conversation?', 'Yes, and by default it is reversible.

Removing a conversation archives it. It disappears from your list, but it is not gone, and we can bring it back if you ask.

There is also a permanent delete, which really does remove it.

If you want everything gone rather than one conversation, Profile, then Privacy Center, has the options for that — including deleting your whole account.', 'walked', 'answered', 'true', NULL, '{/app/ally-chat,/app/profile}', '2026-09-05', 'The delete endpoint defaults to archive mode and a restore endpoint exists. Permanent removal is a separate explicit mode.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('95', '8', 'talking-to-ally', 'Talking to Ally', 'What''s the difference between Ally chat and the diagnosis?', 'The diagnosis is a one-off. Chat is the everyday part.

The diagnosis is a structured conversation that happens once. Ally asks the questions, in an order it chooses, and it ends with your report.

Chat is the opposite way round — you ask, about anything, whenever you like. Ally already knows your report and remembers your business, so you are carrying on a conversation rather than starting from scratch.

One finds the problem. The other helps you work on it.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis,/app/ally-chat}', '2026-09-05', 'Separate flows with separate endpoints. Chat receives the diagnosis as context.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('96', '8', 'talking-to-ally', 'Talking to Ally', 'Does Ally know what''s in my report when I''m chatting to it?', 'Yes. Your report is part of what Ally has in front of it every time you chat.

So you can ask about any part of it — what a section meant, why it reached a conclusion, what to do about the root cause first — without pasting anything in.

The quickest way in is the "Discuss this with Ally" button at the bottom of your report.

It also has your memory and your open tasks, so it can connect the report to what you are actually working on.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/ally-chat}', '2026-09-05', 'The chat prompt carries the diagnosis, the founder''s memory, retrieved knowledge and a diagnostic map, plus open planning tasks.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('97', '8', 'talking-to-ally', 'Talking to Ally', 'Does Ally know my goals, my tasks and my vision?', 'It knows your open tasks from Plan Your Day, and it will connect what you are asking to what is already on your list.

So if you ask about something you have already set yourself, Ally should recognise it rather than suggest it again from scratch.

It does not always have every goal and every line of your Vision in front of it. If something matters to the question, it is worth saying so in the chat — that is never wasted.', 'walked', 'answered', 'true', NULL, '{/app/ally-chat,/app/plan,/app/goals}', '2026-09-05', 'Open Plan Your Day tasks are explicitly flattened into the chat prompt with title, status and priority. Goals and Vision are not carried in the same way.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('98', '8', 'talking-to-ally', 'Talking to Ally', 'Ally''s advice contradicts my report. Which one do I trust?', 'Start with the report, then ask Ally why it differs.

The report came from a long, structured conversation. Chat is quicker and works from whatever you have just said, so if you gave it different information, it may reasonably reach a different answer.

The useful move is to put the contradiction to Ally directly: tell it what your report said and ask why it is now saying something else. That usually clears it up in one reply.

If it does not, please tell us. A real contradiction is something we want to see.', 'walked', 'answered', 'true', NULL, '{/app/report,/app/ally-chat,/app/feedback}', '2026-09-05', 'Chat is grounded on the diagnosis but responds to the immediate message, so new input can move the answer.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('99', '8', 'talking-to-ally', 'Talking to Ally', 'Why won''t Ally answer my question about billing?', 'Because Ally is built to work on your business, not to answer questions about the product itself. It does not know your plan, your allowance or your payments.

For anything like that, the right places are Profile, where the Subscription and billing section lives, and Help & Support, where you can message a person.

If Ally gave you a vague answer rather than sending you there, that is our fault and not yours. We are working on making it point you in the right direction.', 'walked', 'answered', 'true', NULL, '{/app/profile,/app/help}', '2026-09-05', 'LIVE TEST. Asked Ally about plan pricing and cancelling a subscription. It declined to answer, correctly.', 'PRODUCT GAP. Ally declines these questions, but not by design — there is no rule anywhere in the prompts about product, plan or billing questions. It simply has no such knowledge. Worse, it does not recognise the question as being about ITSELF: in the live test it described the subscription as belonging to ''a tool you''re using'' and suggested checking their pricing page. The founder is left with nowhere to go. A short instruction telling Ally to name Help & Support and the billing page when asked about the product would fix this cheaply, and is the same self-knowledge gap the help-bot plan was written for.', NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('100', '8', 'talking-to-ally', 'Talking to Ally', 'Can I ask Ally about legal, tax or investment decisions?', 'You can ask, and Ally will help where it is about your business.

Money, pricing, hiring, a contract you are unsure about, whether to raise -- these are founder questions and Ally will think them through with you.

What it will not do is act as your lawyer, your accountant or your investment adviser. It is a decision-support tool, not professional advice, and for anything with legal or tax consequences you need someone qualified who knows your situation.

Ally also stays on its subject. Ask it for a recipe or advice about your relationship and it will politely say that is not what it is for.', 'walked', 'answered', 'true', NULL, '{/terms,/app/ally-chat}', '2026-09-06', 'Team position, 2026-09-06: Ally is bounded to founder and business content and will not answer irrelevant subjects. The professional-advice limit is Terms section 2, which states plainly that the Platform is a decision-support tool and does not constitute legal, financial or management consulting advice.', 'The subject boundary is now a stated POLICY but is not yet enforced in the prompts. Nothing in the prompt library, knowledge base or grounding prompts tells Ally to decline off-topic questions. Worth adding a line to _PRODUCT_QUESTIONS'' neighbours so the behaviour matches the answer.', 'Team decision, 2026-09-06.', 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('101', '8', 'talking-to-ally', 'Talking to Ally', 'Ally told me something that isn''t true. How do I report that?', 'Please do tell us — it is genuinely useful.

The Feedback page is the quickest route. Choose "Something is broken" if Ally stated a plain fact that is wrong, or "Something confused me" if it was more that the answer did not make sense.

If you can, paste what you asked and what it replied. That makes it far easier for us to find the cause.

Ally is not allowed to invent findings about your business, so a made-up fact is a fault worth chasing, not something to shrug off.', 'walked', 'answered', 'true', NULL, '{/app/feedback}', '2026-09-05', 'Feedback topics confirmed. The grounding rules forbid inventing findings, scores, sources or advice.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('102', '8', 'talking-to-ally', 'Talking to Ally', 'Can I start a fresh conversation, or does everything run together?', 'You can start as many separate conversations as you like. Use New chat and you get a clean thread.

They stay separate in your list, so you can keep one for hiring and another for pricing without them mixing.

What carries across all of them is Ally''s memory of you and your business. So a new conversation is a fresh page, not a fresh start — you never have to explain who you are again.', 'walked', 'answered', 'true', NULL, '{/app/ally-chat}', '2026-09-05', 'New chat creates a conversation and is written not to leave an empty thread behind. Memory is founder-level rather than conversation-level.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('103', '8', 'talking-to-ally', 'Talking to Ally', 'Can I search or export my past conversations?', 'You can export them. There is no search yet, sorry.

To export, go to Profile, then Privacy Center, and use "Download my data". Your conversations and messages come down with everything else, as a file.

Inside the app you can scroll your conversation list and open any thread, but there is no way to search across them for a word. If that would help you, please tell us — it is a fair thing to want.', 'walked', 'answered', 'true', NULL, '{/app/profile,/app/ally-chat}', '2026-09-05', 'Conversations and messages are two of the sections in the data export. No search exists in the chat UI.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('104', '8', 'talking-to-ally', 'Talking to Ally', 'Why do I get a different answer when I ask the same thing twice?', 'Because Ally writes each answer rather than looking one up.

Ask the same question twice and the shape of the answer will usually match, but the words will not be identical. That is normal.

What can change the substance is context. If the conversation has moved on, or you gave a detail in between, Ally takes that into account.

If the two answers actually contradict each other rather than just reading differently, that is worth reporting on the Feedback page.', 'walked', 'answered', 'true', NULL, '{/app/ally-chat,/app/feedback}', '2026-09-05', 'Answers are generated per request with the conversation as context, so wording varies by design.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('105', '8', 'talking-to-ally', 'Talking to Ally', 'Can I talk instead of typing?', 'During the diagnosis, yes — voice is free for everyone there. There is a microphone button, and you can speak your answers instead of typing them.

In Ally chat, voice is part of the paid plans. If it is not available on yours, you will see a note saying so.

Everything works by typing either way. Voice is a convenience, not a different Ally.', 'walked', 'answered', 'true', NULL, '{/app/diagnosis,/app/ally-chat,/app/billing}', '2026-09-05', 'The diagnosis screen states ''Voice input free on every plan here''. Chat gates voice behind a paid feature with the message ''Voice chat is a paid-plan feature. Voice input is available for free during your diagnosis.''', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('106', '8', 'talking-to-ally', 'Talking to Ally', 'The microphone isn''t working.', 'Usually it is one of these.

Your browser needs permission. The first time you use it, a small prompt appears asking to use the microphone — if you dismissed it, you can turn it back on from the padlock icon next to the web address.

It also needs a browser that supports voice input. Chrome is the safest choice; some browsers do not support it at all.

And in the chat, voice may simply not be included on your plan, in which case you will see a note rather than a fault.

If none of that explains it, please tell support which browser and device you are on.', 'walked', 'answered', 'true', NULL, '{/app/help}', '2026-09-05', 'Voice input uses the browser''s own speech support, so availability and permission are browser-level. The chat gate produces a plan message rather than an error.', NULL, 'Browser-by-browser behaviour has not been tested end to end. That test is listed against question 203.', 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('107', '8', 'talking-to-ally', 'Talking to Ally', 'Can I use Ally in Hindi, or another language?', 'Ally works in English at the moment. That is the only language it is built for.

You can write to it in another language and it will often understand you, but its questions, your report and everything else will come back in English. It has not been checked for quality in any other language, so we would not want to promise it.

If you would use Ally in another language, please tell us which one. We are keeping track of what people ask for.', 'walked', 'answered', 'true', NULL, '{/app/feedback}', '2026-09-05', 'The prompt manager is configured with a single supported language, English. A preferred_language setting exists on the account but there are no non-English prompts behind it.', NULL, NULL, 'group-08-talking-to-ally.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('108', '9', 'compass-journey-achievements', 'Compass, Journey, Achievements', 'What is this Compass page actually showing me?', 'It is the short version of your diagnosis, plus what you are aiming at.

At the top are four readings: your overall band, how many areas Ally scored, how many of those came out low enough to flag, and how many reports you have.

Under that is your north star — your Vision and your main goal, or a prompt to set them if you have not.

Then what Ally would flag first, and the stages of your journey.

It is a summary, not a live dashboard. For the full picture, open your report.', 'walked', 'answered', 'true', NULL, '{/app,/app/report}', '2026-09-05', 'Read the live Compass for a founder with a completed report: four readings, north star, ''What Ally would flag first'', and ''Your five stones''.', NULL, NULL, 'group-09-compass-journey-achievements.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('109', '9', 'compass-journey-achievements', 'Compass, Journey, Achievements', 'What does "Founder Clarity: Developing" mean? Is that bad?', 'No, it is not bad. Developing is the middle-upper band and the most common one.

There are four: Critical Gap, Needs Attention, Developing, and Strong. Developing means things are reasonably solid — some gaps and blind spots, but nothing blocking you.

It is a word rather than a number on purpose. A number invites you to chase it, and moving from 61 to 64 would not mean anything real. Moving from Developing to Strong would.

It comes from your latest diagnosis. Your report explains what sits behind it.', 'walked', 'answered', 'true', NULL, '{/app,/app/report}', '2026-09-05', 'Band names and ranges read from the pillar reference data: Critical Gap 0-35, Needs Attention 36-55, Developing 56-75, Strong 76-100. The Compass renders the band word, never the score.', NULL, NULL, 'group-09-compass-journey-achievements.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('110', '9', 'compass-journey-achievements', 'Compass, Journey, Achievements', 'It says 0 red flags. Does that mean nothing''s wrong?', 'It means nothing came out low enough to be treated as urgent. That is genuinely good news, but it is not the same as nothing being wrong.

A red flag is Ally saying one area is bad enough that it is probably holding the others back. Zero of them means no area crossed that line.

You can still have plenty to work on. Your report will name the root cause and your priority actions whether or not anything was flagged.

So read zero red flags as "nothing is on fire", not as "nothing to do".', 'walked', 'answered', 'true', NULL, '{/app,/app/report}', '2026-09-05', 'Red flags on the Compass is a count of pillars below their own threshold. The subtext reads ''None detected'' at zero and ''Needs attention'' otherwise.', NULL, NULL, 'group-09-compass-journey-achievements.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('111', '9', 'compass-journey-achievements', 'Compass, Journey, Achievements', 'What is Journey? Why is it locked?', 'It is not locked — it is not built yet, and the page says so.

Journey is meant to hold the path that shaped how you build: the decisions, lessons and turning points Ally picks up from your story over time. Open it today and you get an honest "coming soon" rather than a locked door.

So there is nothing you need to do to unlock it, and no plan that includes it yet. It will appear when it is ready.

In the meantime, your report and your Founder DNA page cover most of what Journey will eventually show.', 'walked', 'answered', 'true', NULL, '{/app/journey,/app/founder-dna,/app/report}', '2026-09-05', 'The nav entry is flagged coming-soon rather than report-gated, and the page renders its own ''Coming soon'' panel. Nothing gates it on a plan or a report.', NULL, NULL, 'group-09-compass-journey-achievements.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('112', '9', 'compass-journey-achievements', 'Compass, Journey, Achievements', 'How do I unlock achievements?', 'By talking to Ally. Achievements open up after 15 messages.

The page shows you exactly where you are — for example "You''re at 6 of 15 messages" — with a progress bar, so you are never guessing.

It works that way because achievements come from what Ally learns about you in conversation. Before there is enough of your story, they would not mean anything.

There is no payment involved and nothing to claim. Just carry on using Ally and it opens by itself.', 'walked', 'answered', 'true', NULL, '{/app/achievements,/app/ally-chat}', '2026-09-05', 'The unlock threshold is 15 messages, enforced server-side rather than in the UI. The gate renders live progress against it.', NULL, NULL, 'group-09-compass-journey-achievements.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('113', '9', 'compass-journey-achievements', 'Compass, Journey, Achievements', 'My clarity number changed and I didn''t do anything. Why?', 'Your band should not change on its own. It comes from your diagnosis, and your diagnosis does not get re-run or re-scored in the background.

Two things on the Compass do move without you doing anything to your diagnosis: the report count, and the number of sessions underneath it.

If the band itself genuinely changed — say from Developing to Needs Attention — that is not expected, and we would want to know. Please tell support what it said before and what it says now.

Everything else on the page reflects the day you did your diagnosis.', 'walked', 'answered', 'true', NULL, '{/app,/app/help}', '2026-09-05', 'The Compass reads the stored report. Reports are frozen snapshots and nothing recomputes them, so the band is fixed while counts can change.', NULL, NULL, 'group-09-compass-journey-achievements.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('114', '9', 'compass-journey-achievements', 'Compass, Journey, Achievements', 'What is "AI sessions" counting?', 'There is no AI sessions reading on the Compass, so this may be from an older version or another product — sorry for the confusion.

What you will see is a Reports count, with the number of completed sessions written underneath it. A session means one full run of the diagnosis, so for most founders that number is one.

The other three readings are your overall band, how many areas Ally scored, and how many were flagged.

If you are looking at something that does say "AI sessions", please send us a screenshot — we would like to see where it is.', 'walked', 'answered', 'true', NULL, '{/app,/app/help}', '2026-09-05', '''AI Sessions'' exists only in the frontend''s mock-data file, which no page imports for these readings. The live Compass shows Founder clarity, Dimensions scanned, Red flags and Reports.', NULL, NULL, 'group-09-compass-journey-achievements.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('115', '9', 'compass-journey-achievements', 'Compass, Journey, Achievements', 'Do achievements get me anything, or are they just badges?', 'They are for you, not for us. There is no discount, no extra allowance and no unlock behind them.

They are a record of what you have actually done and what Ally has learned about you along the way. Founder work is long and quiet, and it is easy to forget how far you have come — that is what they are for.

You can add your own as well, and edit or remove any of them.

If you would rather they did something more, tell us. Nobody has decided that they never will.', 'walked', 'answered', 'true', NULL, '{/app/achievements,/app/feedback}', '2026-09-05', 'Achievements are founder-editable records with create, edit and delete. Nothing in the plan catalog or the feature gates references them.', NULL, NULL, 'group-09-compass-journey-achievements.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('116', '9', 'compass-journey-achievements', 'Compass, Journey, Achievements', 'Is any of this live, or is it all from the day I did the diagnosis?', 'Mostly from the day you did your diagnosis, and the page says so — three of the four readings carry the line "From your latest diagnosis".

What does move: your report count, your completed sessions, your Vision and goals when you edit them, and your tasks in Plan Your Day.

What does not move: your band, the areas scored, and the red flags. Those are fixed to your diagnosis, and there is one diagnosis per account.

So treat the Compass as a summary you can come back to, and Plan Your Day as the part that tracks what you are doing now.', 'walked', 'answered', 'true', NULL, '{/app,/app/plan,/app/goals}', '2026-09-05', 'Three readings render the subtext ''From your latest diagnosis''. The north-star panel reads live Vision and goals. Reports and sessions come from live counts.', NULL, NULL, 'group-09-compass-journey-achievements.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('117', '10', 'founder-dna-business-dna-vision', 'Founder DNA, Business DNA, Vision', 'What is my Founder DNA and what am I supposed to do with it?', 'It is Ally''s read of how you work — how you decide, what drives you, where you tend to get stuck.

The page has three parts: how you operate, your motivation and archetype, and your vision. The archetype is matched from your own words in the diagnosis, and it shows you which words it matched on.

What to do with it: read it once, and notice what you recognise. It is most useful as a lens on the business problem rather than on its own — the same constraint that shows up in how you work usually shows up in the company too.

It is not a label, and nobody else sees it.', 'walked', 'answered', 'true', NULL, '{/app/founder-dna,/app/report}', '2026-09-05', 'Read the live Founder DNA page: hero, ''How you operate'', ''Motivation & archetype'' with matched terms, and ''Your vision''.', NULL, NULL, 'group-10-founder-dna-business-dna-vision.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('118', '10', 'founder-dna-business-dna-vision', 'Founder DNA, Business DNA, Vision', 'Can I redo Founder DNA if I answered badly?', 'Not on its own, sorry. Founder DNA comes out of the diagnosis, and there is one diagnosis per account.

It also could not really be redone by itself. What Ally learns about you is what it reads your business answers through, so changing one without the other would leave the two halves disagreeing.

What helps now: open Ally chat and tell it what you would have said. It will work with the fuller picture from then on, even though the page itself stays as it is.

If your answers were badly off, contact support and we will look at it with you.', 'walked', 'answered', 'true', NULL, '{/app/ally-chat,/app/help}', '2026-09-05', 'No partial re-run exists. The only reset is a whole-diagnosis admin action, used case by case.', NULL, NULL, 'group-10-founder-dna-business-dna-vision.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('119', '10', 'founder-dna-business-dna-vision', 'Founder DNA, Business DNA, Vision', 'What''s Business DNA, and how is it different from Founder DNA?', 'Founder DNA is about you. Business DNA is about the company.

Business DNA scores your business across six areas: Founder Readiness, Market Clarity, Revenue Maturity, Product & Execution, Team & Leadership, and Strategic Clarity. Each one lands in a band — Critical Gap, Needs Attention, Developing or Strong.

Founder DNA is how you decide and operate. Business DNA is how the business currently runs.

The point of having both is what sits between them. Ally looks for the place where a pattern of yours and a weakness in the business meet, and that is usually the root cause.', 'walked', 'answered', 'true', NULL, '{/app/business-dna,/app/founder-dna}', '2026-09-05', 'Pillar names and band names read from the reference data. The Business DNA page renders ''Business dimensions''.', NULL, NULL, 'group-10-founder-dna-business-dna-vision.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('120', '10', 'founder-dna-business-dna-vision', 'Founder DNA, Business DNA, Vision', 'Why is Business DNA locked?', 'Because it is built from your diagnosis, and there is nothing to show before you have done one.

It is not a paid feature and there is nothing to buy. Finish the diagnosis and both Business DNA and Founder DNA open up, along with your report.

If you have already finished a diagnosis and it still looks locked, that is a fault rather than a setting. Please tell support.', 'walked', 'answered', 'true', NULL, '{/app/business-dna,/app/diagnosis,/app/help}', '2026-09-05', 'The sidebar gates Founder DNA and Business DNA on a report existing. Neither appears in the plan catalog''s feature gates as a paid item.', NULL, NULL, 'group-10-founder-dna-business-dna-vision.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('121', '10', 'founder-dna-business-dna-vision', 'Founder DNA, Business DNA, Vision', 'What''s Vision for? Do I have to fill it in?', 'No, it is completely optional. Nothing is blocked if you leave it empty.

Vision is a place to write down where you are actually trying to get to, across six areas: your life, the business, the impact you want, the financial picture, your ideal day, and what you want to leave behind. Each one takes a sentence or two, and you can add a picture.

What you write shows on your Compass as your north star, so it is in front of you rather than in a document you never open.

It is for you. It is not scored and nobody else sees it.', 'walked', 'answered', 'true', NULL, '{/app/vision,/app}', '2026-09-05', 'Six territory keys confirmed: life, business, impact, financial, ideal_day, legacy — each with a statement, two tags and an optional image, plus a summary. The Compass north-star panel reads it.', NULL, NULL, 'group-10-founder-dna-business-dna-vision.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('122', '10', 'founder-dna-business-dna-vision', 'Founder DNA, Business DNA, Vision', 'Does Ally actually use my vision, or is it just for me to look at?', 'Honest answer: mostly the second, for now.

When you chat with Ally it does not read your Vision page. It works from your diagnosis, what it remembers about you, your open tasks, and the profile you filled in at the start — which does include the one-year vision and 90-day goal you gave then.

So Ally knows roughly where you said you were heading. It does not see the six areas you wrote on the Vision page.

If your vision matters to a question, say it in the chat and Ally will use it. And we would like to close this gap — it is a fair thing to expect.', 'walked', 'answered', 'true', NULL, '{/app/vision,/app/ally-chat}', '2026-09-05', 'Traced the whole chat context assembly. It injects memory, retrieval, a diagnostic map, attachments, open plan tasks and an onboarding profile brief. That brief carries current challenges, the 90-day goal and the one-year vision. Nothing reads vision_territories or vision_summary.', 'PRODUCT GAP. The Vision page is the fullest statement a founder ever writes about where they are trying to get to, and the AI meant to help them get there never sees it. Same for Goals. Worth including in whatever change next widens chat context.', NULL, 'group-10-founder-dna-business-dna-vision.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('123', '10', 'founder-dna-business-dna-vision', 'Founder DNA, Business DNA, Vision', 'Founder DNA is in my report and it''s also a page. What''s the difference?', 'Same source, two different jobs.

The section in your report is the short version, written as part of the diagnosis and fixed to the day it was made. It is there because the rest of the report is built on it.

The page is the fuller view you can come back to — how you operate, your motivation and archetype, and your vision, laid out to read rather than to support an argument.

Neither changes on its own. If they ever disagree, please tell us, because they should not.', 'walked', 'answered', 'true', NULL, '{/app/founder-dna,/app/report}', '2026-09-05', 'The Founder DNA page hero takes its heading from the report''s own Founder DNA section, then adds the operating, archetype and vision panels.', NULL, NULL, 'group-10-founder-dna-business-dna-vision.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('124', '10', 'founder-dna-business-dna-vision', 'Founder DNA, Business DNA, Vision', 'We''ve pivoted. Can I change my Business DNA?', 'Not directly, no. Business DNA comes from your diagnosis, and it stays as it was on the day you did it.

That is worth knowing rather than working around: after a real pivot, the scores describe the business you used to have. Read them with the date in mind.

Running the diagnosis again after a change of stage is something we intend to add, but it is not available yet.

What you can do now is tell Ally in the chat what changed. It will work from that going forward. And if the pivot was large, contact support and we will look at your case.', 'walked', 'answered', 'true', NULL, '{/app/business-dna,/app/ally-chat,/app/help}', '2026-09-05', 'Business DNA is stored on the report, which is a frozen snapshot. One diagnosis per account on every plan.', NULL, NULL, 'group-10-founder-dna-business-dna-vision.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('125', '10', 'founder-dna-business-dna-vision', 'Founder DNA, Business DNA, Vision', 'Is Founder DNA a personality test? Which one is it based on?', 'No, and it is not based on any of the well-known ones.

There is no questionnaire scored against a published personality model, and you will not get a four-letter type. Ally reads what you actually wrote about your own situation during the diagnosis and looks for patterns in it.

The archetype it shows you is matched from your own words — the page even lists which words it matched on, so you can see where it came from.

So treat it as a read of how you were working at that moment, not a fixed type. If it does not sound like you, say so.', 'walked', 'answered', 'true', NULL, '{/app/founder-dna,/app/feedback}', '2026-09-05', 'The archetype card states ''from your own words in the diagnosis'' and renders the matched terms. Nothing in the product references an external personality instrument.', NULL, NULL, 'group-10-founder-dna-business-dna-vision.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('126', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'What''s the difference between Goals and Plan Your Day?', 'Goals are what you are trying to achieve. Plan Your Day is what you are doing about it today.

A goal is bigger and slower — grow revenue, hire a second engineer, get to a repeatable sales process. It sits there while you work towards it.

Plan Your Day is the short list of actual tasks, with times if you want them. It is where the work happens.

Most founders set a handful of goals and rarely change them, then live in Plan Your Day. If you only look at one, look at that one.', 'walked', 'answered', 'true', NULL, '{/app/goals,/app/plan}', '2026-09-05', 'Separate features with separate storage: goals hold outcomes, planning holds dated tasks with status.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('127', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'Does Ally know about my goals when I''m talking to it?', 'It knows your open tasks from Plan Your Day, and it will connect what you are asking to something already on your list.

It does not currently read your Goals page. So if a goal matters to what you are asking, mention it in the chat — Ally will use it straight away, it just will not have picked it up on its own.

It also knows the 90-day goal and one-year vision you gave during onboarding, because those were part of your profile.

We would like to close this gap. It is a fair thing to expect.', 'walked', 'answered', 'true', NULL, '{/app/goals,/app/ally-chat}', '2026-09-05', 'Traced the chat context: open plan tasks are injected with title, status and priority. Nothing reads the goals tables. The onboarding brief does carry the 90-day goal and one-year vision.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('128', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'Where do my recommendations come from? Did a person write these?', 'They come from your diagnosis. No person wrote them for you.

They are part of your report — the same analysis, shown on their own page so you can work through them without opening the whole document.

So they are specific to what Ally found in your answers, not a general list of good advice. If a recommendation does not match your business, that is worth telling us, because it means the finding behind it may be off.

If you want a person involved, you can book a discovery call and go through them together.', 'walked', 'answered', 'true', NULL, '{/app/recommendations,/app/report,/app/discovery-call}', '2026-09-05', 'Recommendations are served as a section of the report itself, generated from the diagnosis with no human review step anywhere in the path.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('129', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'Why do I only have two or three recommendations?', 'Because that is the most you can actually act on, and because Ally would rather give you three real ones than six padded ones.

The plan is built as up to three moves to confirm what is really going on, and up to three to fix it. That is a ceiling, not a target — if only two are worth doing, you get two.

It is deliberate. A list of ten actions reads as thorough and gets nothing done. Three ordered ones, where the first makes the second easier, usually do.

Start at the top and work down.', 'walked', 'answered', 'true', NULL, '{/app/recommendations,/app/next-steps}', '2026-09-05', 'The action plan is capped at three confirm/isolate actions and three solve actions, explicitly documented as a ceiling rather than a quota.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('130', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'What''s the difference between recommendations and next steps?', 'Same advice, two different views.

Recommendations are the thinking — what Ally suggests and why, straight from your diagnosis.

Next steps is the working list. It is where you actually pick things up, tick them off, and see what is left.

So read Recommendations once to understand the reasoning, then live in Next steps. And when you commit to doing something on a particular day, put it in Plan Your Day — that is the list that runs your week.', 'walked', 'answered', 'true', NULL, '{/app/recommendations,/app/next-steps,/app/plan}', '2026-09-05', 'Both are gated on a report existing and both trace back to the same diagnosis output.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('131', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'What are frameworks and how do I actually use one?', 'They are short, practical thinking tools — ten of them, each for a particular kind of decision.

Open one and you get the idea explained plainly, with how to apply it. There is a space for your own notes underneath, so you can write what it means for your business. Those notes are yours and Ally never writes them for you.

The useful way to use one is with a real decision in front of you rather than as reading. Pick the one that matches what you are stuck on, work your problem through it, and write down what came out.

Ally remembers which ones you have opened.', 'walked', 'answered', 'true', NULL, '{/app/frameworks}', '2026-09-05', 'Ten frameworks in the library. Per-founder usage records last-opened and the founder''s own note, explicitly never AI-written.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('132', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'Are the frameworks picked for me, or does everyone see the same ones?', 'Everyone sees the same ten. They are a library, not a recommendation.

What is personal is what you do with them — which ones you have opened, when, and the notes you have written on each.

So nothing here is chosen for you based on your diagnosis. If you want to know which one fits your situation, ask Ally in the chat — it knows your report and can point you at the right one.

If frameworks picked for you would be more useful, tell us. It is a reasonable thing to want.', 'walked', 'answered', 'true', NULL, '{/app/frameworks,/app/ally-chat,/app/feedback}', '2026-09-05', 'The framework list is a fixed set of ten shipped with the app, identical for every founder. Only usage and notes are per-founder.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('133', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'What''s the difference between a task and a goal?', 'A task is one thing you do. A goal is what all those things add up to.

"Call five customers this week" is a task. "Understand why people churn" is a goal.

Tasks live in Plan Your Day, can have a time on them, and get ticked off. Goals live on the Goals page and stay put while you work towards them.

If you are not sure which something is, ask whether you could finish it in a sitting. If yes, it is a task.', 'walked', 'answered', 'true', NULL, '{/app/plan,/app/goals}', '2026-09-05', 'Tasks carry a status and an optional time and are completed; goals are outcomes without completion mechanics.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('134', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'Can I set a time for a task, and will I get a reminder?', 'You can set a time, yes. The reminder is the weaker half.

Ally will nudge you inside the app about anything due or overdue. But it does not email you and there are no phone notifications, so if Ally is closed, nothing reaches you.

If you have connected a calendar, your tasks go onto it — and then your calendar reminds you, which works whether Ally is open or not. That is the most reliable option today.

We know in-app-only is a real limitation and we would like to fix it.', 'walked', 'answered', 'true', NULL, '{/app/plan}', '2026-09-05', 'Nudges are computed client-side from due and overdue tasks. Only discovery-call notifications send email. Connected calendars receive a real event push.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('135', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'There are four different lists telling me what to do. Which is the real one?', 'Plan Your Day. That is the one to work from.

Here is how the others relate to it. Your report names the priority actions — that is the thinking. Recommendations is the same advice on its own page. Next steps is the working list of those actions.

When you decide you are actually going to do something, put it in Plan Your Day with a day and a time. That is the only list built for doing rather than reading.

So: report to understand, Next steps to choose, Plan Your Day to work.', 'policy', 'answered', 'true', NULL, '{/app/plan,/app/next-steps,/app/recommendations,/app/report}', '2026-09-05', 'Settled position: Plan Your Day is the founder''s real to-do list; the other surfaces feed it.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('136', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'What happens when I tick something off? Does anything update?', 'Yes. Your completed count goes up and the task leaves your open list.

That count is how progress is actually measured in Ally. Your report is fixed at the day you made it, so it does not move — what moves is how many of its actions you have done. Your Compass reflects that.

What does not happen: your bands do not change, and nothing gets re-scored. Ticking off a task is a record of work done, not a new diagnosis.

So it is worth ticking things off honestly rather than tidily.', 'walked', 'answered', 'true', NULL, '{/app/plan,/app/next-steps,/app}', '2026-09-05', 'The dashboard tracks actions_open against actions_completed. Nothing recomputes report bands from task completion.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('137', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'Will Ally hold me to this? Does it check in?', 'Only while you are in the app, and honestly that is a limitation.

When you open Ally, it will nudge you about anything overdue or due today. If you have connected a calendar, your tasks are on it and it will remind you properly.

What Ally will not do is chase you. It does not email you, it will not message you, and it cannot notice on a Thursday that you have not opened it since Monday.

So the accountability has to come from you opening it. If you would like Ally to check in properly, tell us — you would not be the first to ask.', 'walked', 'answered', 'true', NULL, '{/app/plan,/app/feedback}', '2026-09-05', 'Nudges are computed only while the founder is in the app. No scheduled worker sends anything, and the reminders table is not polled.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('138', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'Can a framework be applied to my business, or is it just something to read?', 'It does not apply itself, but it is not only reading either.

Each framework has a space for your own notes, and that is where it becomes about your business — you work your actual problem through it and write down what came out. Those notes stay with the framework, so you can come back to them.

Ally will not fill a framework in for you. But you can bring one into the chat: say which framework and what you are deciding, and it will think it through with you using what it knows about your business.

That combination is where they earn their keep.', 'walked', 'answered', 'true', NULL, '{/app/frameworks,/app/ally-chat}', '2026-09-05', 'Framework notes are stored per founder and documented as never AI-written. Nothing auto-applies a framework to a founder''s data.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('139', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'Does the calendar actually put tasks in my Google Calendar?', 'Yes, if you have connected one. Tasks you set in Plan Your Day are added to your Google Calendar as real events, and edits follow.

That also makes it the most reliable way to be reminded, because your calendar can reach you when Ally is closed and Ally itself cannot.

You connect it from Plan Your Day. If you cannot see a Connect option, calendar syncing is not switched on for your account yet.

If you connected one and nothing is appearing, please tell support — that is a fault and we would want to see it.', 'walked', 'answered', 'true', NULL, '{/app/plan,/app/help}', '2026-09-05', 'A real push exists: creating or editing a task pushes an event and records the outcome. The Connect button is hidden entirely where the OAuth client is not configured.', 'RESOLVED 2026-09-05. An earlier note here worried that no founder had ever connected a calendar, because the connections table was empty. That table was in Supabase, which is NOT the production database — production runs on AWS RDS. Confirmed by the team that calendar sync works on the real domain and that they have connected their own. The answer stands as written.', NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('140', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'Can I turn notifications off?', 'Yes. Go to Profile, then Preferences, and switch Notifications off.

That stops the nudges Ally shows you inside the app — reminders about tasks, replies, and updates about your report.

It does not change anything outside the app, because there is nothing to change: Ally does not send reminder emails or phone notifications. The only email it sends is about discovery calls.

If you have connected a calendar, its reminders are separate and keep working. You would turn those off in your calendar, not here.', 'walked', 'answered', 'true', NULL, '{/app/profile}', '2026-09-05', 'The Notifications switch controls in-app nudges. Only discovery-call notifications send email anywhere in the product.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('141', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'What is Know My Energy for?', 'It is not built yet, and the page says so rather than pretending.

The idea is to look at how your energy actually moves through a week — when you do your sharpest work, when you are running on empty — and use that to plan around it instead of against it.

Today there is nothing to use. Opening it gives you an honest "coming soon".

Until then, Plan Your Day is where you shape your week, and Ally will talk through your working patterns with you if you ask it.', 'walked', 'answered', 'true', NULL, '{/app/know-my-energy,/app/plan,/app/ally-chat}', '2026-09-05', 'The page renders a deliberate ''Coming soon'' panel. Nothing behind it exists.', NULL, NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('142', '11', 'goals-steps-frameworks-planning', 'Goals, steps, frameworks, planning', 'I''m on Pro and Know My Energy does nothing.', 'You are right, and we are sorry — that is our mistake rather than anything wrong with your account.

Know My Energy is listed against the top plan, but the feature itself has not been built yet. So there is nothing to unlock and nothing you are missing out on by comparison with anyone else. Nobody has it.

It should not have been presented as something your plan includes while it does not exist, and we are fixing how it is shown.

If you upgraded specifically for it, please contact support and tell us. That is a fair thing to raise.', 'walked', 'answered', 'true', NULL, '{/app/know-my-energy,/app/help}', '2026-09-05', 'The feature is declared in the plan catalog against the top tier, with a code comment stating the founder-facing implementation is still to be built. The page confirms it.', 'The plan catalog advertises Know My Energy on the top tier while the page renders ''Coming soon''. Either remove it from the tier''s feature list until it exists, or mark it as coming soon on the pricing page. Selling a named feature that does nothing is the kind of thing a paying founder remembers.', NULL, 'group-11-goals-steps-frameworks-planning.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('143', '12', 'human-help-and-calls', 'Human help and calls', 'What happens on a discovery call, and who am I talking to?', 'It is 30 minutes with someone from our team, not a bot.

You pick a time that suits you, and the team confirms it. Once they do, your call appears under "Your calls" on the Discovery call page with a Join button, and you also get an email with the time and the link.

The useful version of the call is you bringing something specific: your report, a decision you are stuck on, or a finding you disagree with. Say what you want to cover when you request it, and they will come prepared.

It is a conversation, not a presentation.', 'walked', 'answered', 'true', NULL, '{/app/discovery-call}', '2026-09-05', 'Walked 2026-09-05. The join link is now shown on the calls list for a confirmed call, and a pending one says the link follows confirmation. Before today the link was in the API response and never rendered, and with email unconfigured there was no route to it at all.', NULL, 'Deliberately says the link is on the page FIRST and the email second. The page is the path that cannot silently fail; the email depends on EMAIL_HOST being configured.', 'group-12-human-help-and-calls.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('144', '12', 'human-help-and-calls', 'Human help and calls', 'Is the discovery call free? Why can''t I book one?', 'It is not free. A discovery call costs Rs 300 for 30 minutes, on every plan.

That is per call. No plan includes one, so nobody has an allowance to run out of.

Asking for a slot costs nothing, though. You pick a time and send the request, our team checks it against their diary and confirms, and payment comes after that -- once you know the call is actually happening.

If the button is not there at all, it is because discovery calls are not included on the free plan.', 'walked', 'answered', 'true', NULL, '{/app/discovery-call}', '2026-09-05', 'Team decision 2026-09-05: Rs 300 per 30-minute discovery call, on every plan, with no included allowance anywhere. CALL_PRICE_INR raised from 199 to 300 in the catalog the same day; free_calls_per_month is 0 on all four tiers. The two prices were deliberately separated -- Starter is Rs 199 a month, a call is Rs 300 -- so a founder can tell them apart.', NULL, 'Price set by the team on 2026-09-05. Raised from Rs 199 so it is not confused with the Rs 199 monthly Starter plan.', 'group-12-human-help-and-calls.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('145', '12', 'human-help-and-calls', 'Human help and calls', 'How many calls do I get, and what does an extra one cost?', 'As many as you like, and each one costs Rs 300.

There is no limit and no allowance. Book one call or book six -- every one is Rs 300 for 30 minutes, and it is the same price on every plan.

So there is no such thing as an extra call here. There is just the next call, at the same price as the last one.

You are only charged once the team has confirmed the time. Requesting a slot costs nothing.', 'walked', 'answered', 'true', NULL, '{/app/discovery-call}', '2026-09-05', 'Team decision 2026-09-05: Rs 300 per 30-minute discovery call, on every plan, with no included allowance anywhere. CALL_PRICE_INR raised from 199 to 300 in the catalog the same day; free_calls_per_month is 0 on all four tiers. The two prices were deliberately separated -- Starter is Rs 199 a month, a call is Rs 300 -- so a founder can tell them apart.', NULL, 'Price set by the team on 2026-09-05. Raised from Rs 199 so it is not confused with the Rs 199 monthly Starter plan.', 'group-12-human-help-and-calls.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('146', '12', 'human-help-and-calls', 'Human help and calls', 'Do unused calls roll over?', 'There is nothing to roll over. Calls are not an allowance.

No plan includes free calls, so there is no monthly quota to use or lose. Each call is requested and paid for on its own, at Rs 300 for 30 minutes.

Which means you are never missing out by not booking this month. Book one when you actually need one.', 'walked', 'answered', 'true', NULL, '{/app/discovery-call}', '2026-09-05', 'Team decision 2026-09-05: Rs 300 per 30-minute discovery call, on every plan, with no included allowance anywhere. CALL_PRICE_INR raised from 199 to 300 in the catalog the same day; free_calls_per_month is 0 on all four tiers. The two prices were deliberately separated -- Starter is Rs 199 a month, a call is Rs 300 -- so a founder can tell them apart.', NULL, 'Price set by the team on 2026-09-05. Raised from Rs 199 so it is not confused with the Rs 199 monthly Starter plan.', 'group-12-human-help-and-calls.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('147', '12', 'human-help-and-calls', 'Human help and calls', 'Can I just talk to a person instead of doing all this?', 'You can, and a discovery call is how.

It is worth knowing what you lose, though. Without the diagnosis, whoever you speak to is starting from scratch in 30 minutes, the same as any first meeting. With it, they already know how you work and what Ally found, and the call starts somewhere useful.

So if you have the time, do the diagnosis first and bring the report. If you do not, request a call anyway and say what is going on.

For anything shorter, message support and a person will reply.', 'walked', 'answered', 'true', NULL, '{/app/discovery-call,/app/help}', '2026-09-05', 'Tested end to end after rebuilding the flow: requested a slot (pending, no meeting), rescheduled it (stayed pending), and cancelled it.', NULL, NULL, 'group-12-human-help-and-calls.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('148', '12', 'human-help-and-calls', 'Human help and calls', 'Is the call going to be a sales pitch?', 'It is not meant to be, and if it turns into one we would want to know.

The point of the call is your situation — going through your report, a decision you are stuck on, or something you think Ally got wrong.

If paid help would genuinely suit what you describe, they may mention it. What should not happen is a call that becomes a pitch when you came with a problem.

If that is what you get, please tell us afterwards. It is the kind of thing we would want to correct rather than defend.', 'policy', 'answered', 'true', NULL, '{/app/discovery-call,/app/feedback}', '2026-09-05', 'Tested end to end after rebuilding the flow: requested a slot (pending, no meeting), rescheduled it (stayed pending), and cancelled it.', NULL, NULL, 'group-12-human-help-and-calls.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('149', '12', 'human-help-and-calls', 'Human help and calls', 'How do I move or cancel a call I''ve booked?', 'You can do both yourself, from your call in the app.

Cancel it if you no longer need it, or reschedule it to a different time — you do not have to email anyone. If the call was already confirmed, rescheduling creates the new meeting and sends you a fresh link. If it was still waiting on the team, it simply moves to the new time and stays with them.

Please change it as early as you can. The slot goes back for someone else, and the team plans their week around what is booked.', 'walked', 'answered', 'true', NULL, '{/app/help,/app/discovery-call}', '2026-09-05', 'Tested end to end after rebuilding the flow: requested a slot (pending, no meeting), rescheduled it (stayed pending), and cancelled it.', 'RESOLVED. Cancel and reschedule did not exist in the app or the API when this group was first written; a founder had to email support. Both are now built and tested. Rescheduling preserves whether the call was a request or a confirmed booking, so a moved request does not silently become a booking.', NULL, 'group-12-human-help-and-calls.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('150', '13', 'plans-and-what-you-get', 'Plans and what you get', 'What do I get if I upgrade?', 'It depends which plan you move to — they add different kinds of thing.

Starter gives you the diagnosis and the Clarity Report it writes. That is the honest answer of what is wrong and what to do about it.

Plus adds the part where you work on it: talking to Ally, your Next steps, Goals and Plan Your Day.

Pro adds the standing-advisor pieces — Vision, Recommendations, asking Ally about our wider knowledge, email updates, and priority when you ask for a call.

Your billing page shows what you are on now and exactly what changes.', 'generated', 'answered', 'true', NULL, '{/app/billing}', '2026-09-05', 'Feature bundles read from the plan catalog: base (diagnosis, report, call booking), workspace (chat, voice in chat, next steps, goals, planning), advisor (vision, recommendations, knowledge chat, email notifications, priority calls, Know My Energy).', NULL, 'Deliberately names no prices. They are rendered from the catalog on the billing page, and printing them here would put a second copy in the world that goes stale.', 'group-13-plans-and-what-you-get.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('151', '13', 'plans-and-what-you-get', 'Plans and what you get', 'What''s actually different between Free, Starter and Pro?', 'There are four plans now, not three — Free, Starter, Plus and Pro.

The simplest way to see it is what each one lets you do.

Every plan gives you the diagnosis and your report, and lets you request a discovery call.

Starter stops there. It is the diagnosis and the report, and nothing else.

Plus adds the working part: Ally chat, Next steps, Goals and Plan Your Day.

Pro adds the rest — Vision, Recommendations, asking Ally about our wider knowledge, email updates, and priority when you request a call.

Your billing page lays it out side by side with the prices.', 'generated', 'answered', 'true', NULL, '{/app/billing}', '2026-09-05', 'Four tiers confirmed in the catalog. The question named the old three-tier ladder, so the answer corrects it gently rather than answering a question about plans that no longer exist.', NULL, NULL, 'group-13-plans-and-what-you-get.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('152', '13', 'plans-and-what-you-get', 'Plans and what you get', 'If Free already gives me the diagnosis and the report, why would I pay?', 'There is no free plan, so this does not come up any more.

Ally starts at Starter, Rs 199. You pay it once and it buys you a month -- nothing renews. That gives you the diagnosis and the Clarity Report it writes: the honest read of what is actually wrong and what to do about it.

If you saw a free plan mentioned somewhere, that was during our testing period and it has ended.

What you are paying for is the diagnosis, not access to a chat window. That is the part that takes half an hour of your time and gives you something you can act on.', 'walked', 'answered_pending_product_change', 'false', NULL, '{/app/billing}', '2026-09-06', 'Team decision 2026-09-06. Starter: Rs 199 paid ONCE, buying one month -- it does not auto-renew. Plus (Rs 450) and Pro (Rs 999) are monthly subscriptions, with 12 months for the price of 10 if paid annually. A discovery call is Rs 300 per 30 minutes on any plan. GST is included in every price shown.', NULL, 'HELD until PUBLIC_LAUNCH is on -- describes the paid-only launch state. REVISED 2026-09-06: Starter is a one-off payment for a month, not a monthly subscription. The 2026-09-05 draft said it renewed monthly.', 'group-13-plans-and-what-you-get.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
insert into "support_bot_answers" ("question_id", "group_number", "group_slug", "group_title", "question", "answer", "answer_type", "status", "is_published", "blocked_by", "links", "verified_on", "verified_how", "finding", "note", "source_file", "created_at", "updated_at") values ('153', '13', 'plans-and-what-you-get', 'Plans and what you get', 'Why does Free get more chat per day than Starter?', 'It does not any more -- there is no free plan.

Here is the honest shape of it now. Starter is Rs 199, paid once for a month. It is the diagnosis and your report, and it does not include chatting with Ally.

Chat starts at Plus, Rs 450 a month, which also gives you Goals, Next steps and Plan Your Day. Pro, at Rs 999 a month, gives you more of it each day.

So the ladder is: Starter tells you what is wrong. Plus is where you work on it with Ally. If you know you want to talk things through, start at Plus.', 'walked', 'answered_pending_product_change', 'false', NULL, '{/app/billing}', '2026-09-06', 'Team decision 2026-09-06. Starter: Rs 199 paid ONCE, buying one month -- it does not auto-renew. Plus (Rs 450) and Pro (Rs 999) are monthly subscriptions, with 12 months for the price of 10 if paid annually. A discovery call is Rs 300 per 30 minutes on any plan. GST is included in every price shown.', NULL, 'HELD until PUBLIC_LAUNCH is on -- describes the paid-only launch state. REVISED 2026-09-06: Starter is a one-off payment for a month, not a monthly subscription. The 2026-09-05 draft said it renewed monthly.', 'group-13-plans-and-what-you-get.json', '2026-09-06 10:46:27.236539+00', '2026-09-06 10:46:27.236539+00') on conflict do nothing;
